window.EXAM_DATA=[{"year": "111", "num": 1, "type": "單選", "rate": "29%", "img": "img/111_q01.png", "answer": [{"t": "(4)　120"}], "key": "先由「兩球不同口味 C(n,2)>100」定出 n=15；「可同口味」是重複組合。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp2"}, {"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "「兩球不同口味的組合數 C(n,2)>100」→ n(n−1)/2>100 → n(n−1)>200，最小 n=15（15×14=210）。"}, {"type": "text", "c": "顧客任選兩球「可同一口味」＝重複組合 = C(n+1, 2)："}, {"type": "math", "c": "\\binom{15+1}{2}=\\dfrac{15\\times16}{2}=120"}, {"type": "text", "c": "故選 (4)。"}]}, {"year": "111", "num": 2, "type": "單選", "rate": "40%", "img": "img/111_q02.png", "answer": [{"t": "(1)　"}, {"m": "a^2=b^3"}], "key": "設 x=log_a b，誤按得到 log_b a = 1/x；由 1/x =(9/4)x 解 x。", "kaodian": [{"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "設 x=log_a b（正確值）。順序弄錯按成 log_b a = 1/x。題意「誤值 = 正確值的 9/4 倍」："}, {"type": "math", "c": "\\dfrac{1}{x}=\\dfrac{9}{4}x\\Rightarrow x^2=\\dfrac{4}{9}\\Rightarrow x=\\dfrac23\\ (\\because a,b>1)"}, {"type": "text", "c": "即 log_a b=2/3 → b=a^(2/3) → a²=b³。選 (1)。"}]}, {"year": "111", "num": 3, "type": "單選", "rate": "12%", "img": "img/111_q03.png", "answer": [{"t": "(5)　"}, {"m": "y=-\\tfrac{x}{2}"}], "key": "投影後變異最小 ＝ 投影到與「資料散布最大方向（主軸）」垂直的直線。", "kaodian": [{"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp3"}, {"unit": "數據分析", "title": "考點2 相關係數 r", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp2"}], "steps": [{"type": "text", "c": "資料主要沿一條斜率約 2 的直線分布（正相關）。把資料垂直投影到某直線上，投影點的變異在「與散布最大方向垂直」時最小。"}, {"type": "text", "c": "主軸斜率≈2，垂直方向斜率 = −1/2，故投影到 y=−x/2 變異最小。選 (5)。（見右圖）"}], "fig": "img/111_fig_q03.png"}, {"year": "111", "num": 4, "type": "單選", "rate": "57%", "img": "img/111_q04.png", "answer": [{"t": "(3)　"}, {"m": "\\log\\tfrac32"}], "key": "log a1,log a3,log a6 等差 → a3²=a1·a6，解出 a1=4d。", "kaodian": [{"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp1"}, {"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "log 成等差 → 2log a3 = log a1 + log a6 → a3² = a1·a6。代 a3=a1+2d、a6=a1+5d："}, {"type": "math", "c": "(a_1+2d)^2=a_1(a_1+5d)\\Rightarrow 4d^2=a_1 d\\Rightarrow a_1=4d"}, {"type": "text", "c": "則 a1=4d、a3=6d、a6=9d，公差 = log a3 − log a1 = log(6d/4d)=log(3/2)。選 (3)。"}]}, {"year": "111", "num": 5, "type": "單選", "rate": "53%", "img": "img/111_q05.png", "answer": [{"t": "(2)　8"}], "key": "貝氏定理分別算「單次判陰」與「三次皆陰」中的染病機率，再相除。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp4"}, {"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp5"}], "steps": [{"type": "text", "c": "P(染)=0.3、P(陰|染)=0.2、P(陰|未)=0.6。單次判陰中染病："}, {"type": "math", "c": "P=\\dfrac{0.3\\times0.2}{0.3\\times0.2+0.7\\times0.6}=\\dfrac{0.06}{0.48}=\\dfrac18"}, {"type": "text", "c": "三次皆判陰中染病："}, {"type": "math", "c": "P\\,'=\\dfrac{0.3\\times0.2^3}{0.3\\times0.2^3+0.7\\times0.6^3}=\\dfrac{0.0024}{0.1536}=\\dfrac{1}{64}"}, {"type": "math", "c": "\\dfrac{P}{P\\,'}=\\dfrac{1/8}{1/64}=8"}, {"type": "text", "c": "故選 (2)。"}]}, {"year": "111", "num": 6, "type": "單選", "rate": "48%", "img": "img/111_q06.png", "answer": [{"t": "(5)　"}, {"m": "27x+33y=65"}], "key": "正三角形中，兩邊夾角的平分線是對稱軸，第三邊垂直於它。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "正三角形中，L1、L2 夾角的平分線是對稱軸，第三邊 L 垂直於此平分線。平分線斜率 11/9 → L 斜率 = −9/11。"}, {"type": "text", "c": "L 過 (2, 1/3) 斜率 −9/11："}, {"type": "math", "c": "y-\\tfrac13=-\\tfrac{9}{11}(x-2)\\Rightarrow 27x+33y=65"}, {"type": "text", "c": "故選 (5)。"}]}, {"year": "111", "num": 7, "type": "多選", "rate": "57%（全對率 37%）", "img": "img/111_q07.png", "answer": [{"t": "(2)(4)"}], "key": "兩非負數比大小可平方；|5n−21|≥7|n| 等價於 (5n−21)²≥49n²。", "kaodian": [{"unit": "數與式", "title": "考點2 絕對值的意義、方程式與不等式", "url": "https://mathmap-kitty.github.io/web/115學測數學_數與式.html#kp2"}], "steps": [{"type": "text", "c": "兩邊非負，平方後等價：|5n−21|≥7|n| 就是 (5n−21)²≥49n²，(4) 對；也等價於 |7n/(5n−21)|≤1，即 (2) 對。"}, {"type": "math", "c": "(5n-21)^2\\ge 49n^2\\Rightarrow 24n^2+210n-441\\le0\\Rightarrow -10.5\\le n\\le 1.75"}, {"type": "text", "c": "整數 n∈{−10, …, 1} 共 12 個（有限），(5) 錯。(1)(3) 非等價變形，錯。選 (2)(4)。"}]}, {"year": "111", "num": 8, "type": "多選", "rate": "60%（全對率 39%）", "img": "img/111_q08.png", "answer": [{"t": "(1)(4)"}], "key": "先算三邊長，用餘弦定理判斷角，用正弦定理算外接圓半徑。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp2"}, {"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp2"}], "steps": [{"type": "text", "c": "AB=√5、BC=√10、AC=√17。(1) AC 最長，對。(3) AB²+BC²−AC²=−2<0 → 角B 為鈍角，非銳角三角形，錯。"}, {"type": "math", "c": "(4)\\ \\cos B=\\dfrac{5+10-17}{2\\sqrt5\\sqrt{10}}=-\\dfrac{\\sqrt2}{10}\\Rightarrow \\sin B=\\dfrac{7\\sqrt2}{10}\\ (\\text{對})"}, {"type": "text", "c": "(2) 大邊對大角：BC>AB → 角A>角C → sin A>sin C，「sin A<sin C」錯。(5) 2R=AC/sinB=5√34/7，R≈2.08>2，錯。選 (1)(4)。"}]}, {"year": "111", "num": 9, "type": "多選", "rate": "19%（全對率 4%）", "img": "img/111_q09.png", "answer": [{"t": "(3)(4)"}], "key": "用向量係數表示各點；三角形面積、到某邊距離只看對應的分量。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp2"}], "steps": [{"type": "text", "c": "P 在△內 → a,b>0、a+b<1。AQ=(b,a)（係數對調）、AR=(a, b−0.05)。"}, {"type": "text", "c": "(3) △ABP=(b/2)|AB×AC|、△ACQ=(b/2)|AB×AC|，相等，對。(4) P、Q 到 BC 的距離都比例於 1−a−b（對調不變），△BCP=△BCQ，對。"}, {"type": "text", "c": "(1) R 可能 b−0.05<0 跑到△外，錯。(2) |AP|=|AQ| 需 |AB|=|AC|，不一定，錯。(5) △ABP>△ABR 需 b>|b−0.05|，b 很小時不成立，錯。選 (3)(4)。"}]}, {"year": "111", "num": 10, "type": "多選", "rate": "20%（全對率 3%）", "img": "img/111_q10.png", "answer": [{"t": "(1)(2)"}], "key": "g=f(−x)−3；由對稱中心 (1,0)、g(−1)<0 定出 b=3a、c=2a、a<0。", "kaodian": [{"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp5"}, {"unit": "多項式函數", "title": "考點4 高次方程式：有理根、勘根定理與奇偶函數", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp4"}], "steps": [{"type": "text", "c": "g(x)=f(−x)−3=−ax³+bx²−cx。對稱中心 x=b/(3a)=1 → b=3a；g(1)=0 → c=2a；g(−1)=6a<0 → a<0。"}, {"type": "text", "c": "(1) g(x)=−a·x(x−1)(x−2)，三整數根 0,1,2，對。(2) a<0，對。(3) f 的對稱中心是 (−1, 3) 不是 (−1,−3)，錯。"}, {"type": "math", "c": "(4)\\ f(100)=1030200a+3;\\ a\\to0^-\\ \\text{時}\\ f(100)>0,\\ \\text{不一定}<0\\ (\\text{錯})"}, {"type": "text", "c": "(5) x=−1 處切線斜率 f′(−1)=−a≠a，錯。選 (1)(2)。"}]}, {"year": "111", "num": 11, "type": "多選", "rate": "38%（全對率 16%）", "img": "img/111_q11.png", "answer": [{"t": "(2)(3)(4)"}], "key": "兩矩形共邊 AD ⊥ 兩邊 → AD⊥底面，是三角柱；設坐標逐一算角。", "kaodian": [{"unit": "空間向量", "title": "考點6 二面角與立體（摺疊問題）", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp6"}, {"unit": "三角", "title": "考點7 圓周角與二面角中的三角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp7"}], "steps": [{"type": "text", "c": "ADEB、ADFC 皆矩形 → AD⊥AB 且 AD⊥AC → AD⊥底面 ABC（三角柱）。設 A=(0,0,0)、B=(5,6,0)、C=(5,0,0)、D=(0,0,h)、E=(5,6,h)、F=(5,0,h)。"}, {"type": "text", "c": "(1) 沿平面 ACE 切 → 得「四面體 ABCE」＋「四角錐 E–ADFC」，不是兩個四面體，錯。"}, {"type": "text", "c": "(2) 兩矩形沿 AD 的夾角 = ∠BAC，cos∠BAC=5/√61 → ≈50°>45°，對。"}, {"type": "math", "c": "(3)\\ \\cos\\angle CEB=\\dfrac{h}{\\sqrt{36+h^2}}>\\cos\\angle AEB=\\dfrac{h}{\\sqrt{61+h^2}}\\Rightarrow \\angle CEB<\\angle AEB\\ (\\text{對})"}, {"type": "text", "c": "(4) 對各種 h 檢驗，tan∠AEC < sin∠CEB 皆成立，對。(5) ∠CEB>∠AEC，錯。選 (2)(3)(4)。"}]}, {"year": "111", "num": 12, "type": "多選", "rate": "21%（全對率 9%）", "img": "img/111_q12.png", "answer": [{"t": "(1)(2)"}], "key": "(g)²除 f 餘 g → g(g−1)=f·q；用 f 無實根與次數限制推出頂點值範圍。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp1"}, {"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp2"}], "steps": [{"type": "text", "c": "(g)²=f·q+g → g(g−1)=f·q。餘式次數 2 < deg f，故 deg f≥3。"}, {"type": "text", "c": "若 deg f=3（奇數）必有實根，與「f 無實根」矛盾 → deg f=4，f = g(g−1)/常數。"}, {"type": "text", "c": "「f 無實根」等於「g=0、g=1 皆無解」，也就是 g 的最小值（頂點 y 坐標）大於 1。"}, {"type": "text", "c": "故頂點 y 必 >1。不可能的值 = ≤1 者，即 √2/2 與 1。選 (1)(2)。"}]}, {"year": "111", "num": 13, "type": "選填", "rate": "46%", "img": "img/111_q13.png", "answer": [{"t": "選填　"}, {"m": "4.2"}, {"t": " 張"}], "key": "錢只夠 15 次十連抽；每次十連抽的金卡期望 = 9×2% + 1×10%。", "kaodian": [{"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp6"}], "steps": [{"type": "text", "c": "23000÷1500 → 可做 15 次十連抽（15×1500=22500，第 16 次不夠）。每次十連抽的金卡期望："}, {"type": "math", "c": "9\\times0.02+1\\times0.10=0.28"}, {"type": "text", "c": "15 次共 15×0.28 = 4.2 張。"}]}, {"year": "111", "num": 14, "type": "選填", "rate": "21%", "img": "img/111_q14.png", "answer": [{"t": "選填　"}, {"m": "a=2,\\ b=\\tfrac12"}], "key": "由化簡後矩陣解出含 b 的 (x,y,z)，代回原方程組求 a、b。", "kaodian": [{"unit": "矩陣", "title": "考點4 一次聯立方程式與高斯消去法", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp4"}], "steps": [{"type": "text", "c": "由化簡後矩陣：bz=0（唯一解 → b≠0 → z=0）、by=−5 → y=−5/b、x=7−2y=7+10/b。代回原方程組："}, {"type": "math", "c": "\\text{第2式}\\Rightarrow 10-5a=0\\Rightarrow a=2;\\quad \\text{第3式}\\Rightarrow 21-\\dfrac{10}{b}=1\\Rightarrow b=\\dfrac12"}, {"type": "text", "c": "故 a=2、b=1/2。"}]}, {"year": "111", "num": 15, "type": "選填", "rate": "16%", "img": "img/111_q15.png", "answer": [{"t": "選填　"}, {"m": "192"}, {"t": " 平方公尺"}], "key": "由 9/16 得相似比 3/4（定路寬與高）；由 ∠EBC=30° 定路寬，再算面積。", "kaodian": [{"unit": "三角", "title": "考點6 三角形面積比、相似與角平分線", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp6"}, {"unit": "三角", "title": "考點3 三角測量與平面幾何應用", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp3"}], "steps": [{"type": "text", "c": "剩 9/16 → 頂部小三角形相似比 √(9/16)=3/4 → E 在 AC 的 3/4 處、高 = H/4 = 路寬 h。"}, {"type": "text", "c": "新路寬 = C 到直線 BE 的距離 = BC·sin30° = 16×(1/2) = 8 = h → H=32、△ABC=½·16·32=256。"}, {"type": "text", "c": "E 的高 = H/4 = 8，△BCE=½·16·8=64，故 △ABE = 256 − 64 = 192 平方公尺。"}]}, {"year": "111", "num": 16, "type": "選填", "rate": "18%", "img": "img/111_q16.png", "answer": [{"t": "選填　"}, {"m": "x-3y-2z=5"}], "key": "L′在 E 的投影＝L（L′在原平面上）→ E 須垂直原平面，且 E 含 L。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp4"}, {"unit": "空間向量", "title": "考點5 空間中的直線、軌跡與歪斜線", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp5"}], "steps": [{"type": "text", "c": "L′ 在 E 的投影 = L（L′ 在原平面上）→ E 的法向量須垂直原平面法向量 (1,−1,2)，且 E 含 L（法向量⊥L 的方向 (4,2,−1)）："}, {"type": "math", "c": "\\vec{n}_E=(1,-1,2)\\times(4,2,-1)=(-3,9,6)\\parallel(1,-3,-2)"}, {"type": "text", "c": "E 過 L 上一點 (2,−1,0)：x − 3y − 2z = 5。"}]}, {"year": "111", "num": 17, "type": "選填", "rate": "5%", "img": "img/111_q17.png", "answer": [{"t": "選填　"}, {"m": "21"}], "key": "三頂點定底面法向量 n；頂面頂點 T 在 xy 單位圓上，體積 =|T·n+11| 取最大。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp3"}, {"unit": "空間向量", "title": "考點1 空間坐標、距離與正立方體", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp1"}], "steps": [{"type": "text", "c": "底面三頂點求兩邊 u、v，法向量 n=u×v=(8,−6,9)；三頂點都在平面 n·x=−11 上。"}, {"type": "text", "c": "頂面某頂點 T 在 xy 平面單位圓上（|T|=1）。體積 = |(T−底頂點)·n| = |T·n + 11|，其中 T·n=8x−6y 最大 = 10："}, {"type": "math", "c": "V_{\\max}=|10+11|=21"}]}, {"year": "111", "num": 18, "type": "混合題（單選 3 分）", "rate": "55%", "img": "img/111_q18.png", "answer": [{"t": "(4)　"}, {"m": "(\\sqrt3,1)"}], "key": "棒長 1、黑端半徑 √3、白端半徑 2，用距離公式解白端角度。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}, {"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp3"}], "steps": [{"type": "text", "c": "黑端 A(√3,0)，白端 B=(2cosβ, 2sinβ)，由 |AB|=1："}, {"type": "math", "c": "|AB|^2=7-4\\sqrt3\\cos\\beta=1\\Rightarrow \\cos\\beta=\\dfrac{\\sqrt3}{2}\\Rightarrow B=(\\sqrt3,\\ 1)"}, {"type": "text", "c": "故選 (4)。"}], "stem": "img/111_stem.png"}, {"year": "111", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/111_q19.png", "answer": [{"t": "非選　"}, {"m": "\\cos\\angle OA'B'=0"}], "key": "白端停在 B′(−2,0)，解黑端 A′；發現 OA′²+A′B′²=OB′² → 直角。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}, {"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp3"}], "steps": [{"type": "text", "c": "白端停在 B′(−2,0)，黑端 A′=(√3cosα′, √3sinα′)，由 |A′B′|=1 → cosα′=−√3/2 → A′=(−3/2, √3/2)。"}, {"type": "text", "c": "因 |OA′|=√3、|A′B′|=1、|OB′|=2 且 3+1=4，故 ∠OA′B′ 為直角："}, {"type": "math", "c": "\\cos\\angle OA'B'=0,\\qquad A'\\ \\text{的極坐標}=\\left(\\sqrt3,\\ \\dfrac{5\\pi}{6}\\right)"}, {"type": "text", "c": "（與官方參考答案一致）"}], "stem": "img/111_stem.png"}, {"year": "111", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/111_q20.png", "answer": [{"t": "非選　"}, {"m": "\\Omega=\\tfrac{6\\sqrt3-\\pi}{12}"}, {"t": "、"}, {"m": "R=\\tfrac{5\\pi}{12}"}], "key": "因 √3²+1²=2²，棒恆與內圓相切；用扇形加減求面積。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}, {"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp3"}], "steps": [{"type": "text", "c": "因 √3²+1²=2²，掃描棒恆與內圓相切。第一象限 Ω = 扇形OBE + △OAB − 扇形OAD："}, {"type": "math", "c": "\\Omega=\\tfrac12\\cdot\\tfrac{\\pi}{3}\\cdot2^2+\\tfrac12\\cdot\\sqrt3\\cdot1-\\tfrac12\\cdot\\tfrac{\\pi}{2}\\cdot3=\\dfrac{\\sqrt3}{2}-\\dfrac{\\pi}{12}"}, {"type": "text", "c": "R = 扇形OBB′（半徑 2）− 扇形OCC′（半徑 √3），圓心角皆 5π/6："}, {"type": "math", "c": "R=\\tfrac12\\cdot\\tfrac{5\\pi}{6}\\cdot2^2-\\tfrac12\\cdot\\tfrac{5\\pi}{6}\\cdot3=\\dfrac{5\\pi}{3}-\\dfrac{5\\pi}{4}=\\dfrac{5\\pi}{12}"}, {"type": "text", "c": "故 Ω=(6√3−π)/12、R=5π/12。（與官方一致）"}], "stem": "img/111_stem.png"}, {"year": "112", "num": 1, "type": "單選", "rate": "78%", "img": "img/112_q01.png", "answer": [{"t": "(4)　"}, {"m": "N=2^{8}"}], "key": "連按 √ 三次＝取 1/8 次方；反推 N。", "kaodian": [{"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp1"}], "steps": [{"type": "text", "c": "連按 √ 鍵三次，相當於取 N 的 1/8 次方（√√√N = N^(1/8)）。"}, {"type": "math", "c": "N^{1/8}=2\\Rightarrow N=2^{8}"}, {"type": "text", "c": "故選 (4)。"}]}, {"year": "112", "num": 2, "type": "單選", "rate": "59%", "img": "img/112_q02.png", "answer": [{"t": "(5)　"}, {"m": "\\overline{CD}"}], "key": "用切點參數寫切線求 D、E；θ 在直角△ODE 中，tanθ 剛好等於 CD。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}, {"unit": "直線與圓", "title": "考點4 直線與圓的位置：相切、弦長與切線", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp4"}], "steps": [{"type": "text", "c": "設切點 C=(cosφ, sinφ)。切線 x cosφ + y sinφ = 1，交兩軸於 E=(0, 1/sinφ)、D=(1/cosφ, 0)。"}, {"type": "text", "c": "直角三角形 ODE（直角在 O）中，∠OED=θ："}, {"type": "math", "c": "\\tan\\theta=\\dfrac{OD}{OE}=\\dfrac{1/\\cos\\varphi}{1/\\sin\\varphi}=\\tan\\varphi"}, {"type": "text", "c": "另外算得 CD=tanφ（C 在切線上）。故 tanθ = CD，選 (5)。"}]}, {"year": "112", "num": 3, "type": "單選", "rate": "51%", "img": "img/112_q03.png", "answer": [{"t": "(4)　"}, {"m": "t^2=10^{s}"}], "key": "(s, log t) 幾乎是一條斜率約 1/2 的直線 → log t = s/2。", "kaodian": [{"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp3"}, {"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "圖上 (s, log t) 幾乎成一直線，過原點附近、斜率約 1/2。故 log t = (1/2)s："}, {"type": "math", "c": "\\log t=\\dfrac{s}{2}\\Rightarrow t=10^{s/2}\\Rightarrow t^2=10^{s}"}, {"type": "text", "c": "故選 (4)。"}]}, {"year": "112", "num": 4, "type": "單選", "rate": "44%", "img": "img/112_q04.png", "answer": [{"t": "(1)"}], "key": "第 5 位同時是前段最大與後段最大 → 必為 9；其餘選 4 個放左邊即可。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp2"}, {"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "前 5 位遞增、後 5 位遞減，第 5 位是兩段共同的最大 → 必為 9。"}, {"type": "text", "c": "剩下 1~8 這 8 個數，選 4 個放左邊（升冪，唯一排法），其餘 4 個放右邊（降冪）："}, {"type": "math", "c": "\\binom{8}{4}=\\dfrac{8!}{4!\\,4!}"}, {"type": "text", "c": "故選 (1)。"}]}, {"year": "112", "num": 5, "type": "單選", "rate": "47%", "img": "img/112_q05.png", "answer": [{"t": "(2)"}], "key": "PQ、PR 在平面上 → 外積平行法向量 (2,−3,5)；行列式 = 頂列與 (2,−3,5) 的內積 × 定值。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp3"}, {"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp4"}], "steps": [{"type": "text", "c": "PQ、PR 都在平面上，故 PQ×PR 平行於法向量 (2,−3,5)。每個行列式 = 頂列向量·(PQ×PR) = 頂列與 (2,−3,5) 的內積再乘一個相同的定值。"}, {"type": "text", "c": "比較各頂列與 (2,−3,5) 的內積絕對值：(1) 0、(2) 10、(3) 6、(4) 6、(5) 4。"}, {"type": "math", "c": "(2):\\ (1,-1,1)\\cdot(2,-3,5)=2+3+5=10\\ (\\text{最大})"}, {"type": "text", "c": "故選 (2)。"}]}, {"year": "112", "num": 6, "type": "單選", "rate": "35%", "img": "img/112_q06.png", "answer": [{"t": "(3)　"}, {"m": "\\dfrac{6}{7}"}], "key": "用「(向量總和)² = 各長度平方和 + 2×兩兩內積和」一次算出所有內積總和。", "kaodian": [{"unit": "空間向量", "title": "考點2 空間向量的內積、夾角與垂直", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp2"}, {"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp6"}], "steps": [{"type": "text", "c": "O 為原點，其餘 7 個頂點向量的總和 = (4,4,4)、長度平方和 = 12。兩兩內積的總和："}, {"type": "math", "c": "\\sum_{i<j}\\vec{v_i}\\cdot\\vec{v_j}=\\dfrac{|(4,4,4)|^2-12}{2}=\\dfrac{48-12}{2}=18"}, {"type": "text", "c": "共 C(7,2)=21 對，期望值 = 18/21 = 6/7，選 (3)。"}]}, {"year": "112", "num": 7, "type": "多選", "rate": "65%（全對率 46%）", "img": "img/112_q07.png", "answer": [{"t": "(3)(5)"}], "key": "甲每滿 3 月 +200、乙每滿 12 月 +1000；逐項比對月薪與累積總薪。", "kaodian": [{"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp1"}], "steps": [{"type": "text", "c": "起薪同為 S。甲每滿 3 個月調一次 +200、乙每滿 12 個月調一次 +1000。"}, {"type": "text", "c": "(1) 甲第 9 月 = S+400（比第 1 月多 400，不是 600）錯。(2) 第 13 月：甲 S+800 < 乙 S+1000 錯。"}, {"type": "text", "c": "(3) 第 19 月：甲 S+1200 > 乙 S+1000，對。(4) 前 18 月總薪：甲 18S+9000 > 乙 18S+6000，錯。"}, {"type": "text", "c": "(5) 第 3 年（25~36 月）乙都是 S+2000；甲只有第 34、35、36 月為 S+2200 才 > 乙，恰 3 個月，對。故選 (3)(5)。"}]}, {"year": "112", "num": 8, "type": "多選", "rate": "44%（全對率 29%）", "img": "img/112_q08.png", "answer": [{"t": "(1)(4)"}], "key": "用餘事件：n 次至少中 1 次的機率 pₙ = 1 −(0.9)ⁿ。", "kaodian": [{"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp5"}], "steps": [{"type": "math", "c": "p_n=1-(0.9)^n"}, {"type": "text", "c": "(1) (0.9)^(n+1)<(0.9)^n → p_(n+1)>pₙ，對。(2) p₃=1−0.729=0.271≠0.3，錯。(3) 相鄰差 0.1·(0.9)ⁿ 非定值，不是等差，錯。"}, {"type": "text", "c": "(4) 第一次未中、第二次中 = 0.9×0.1 = 0.09；而 p₂−p₁ = 0.19−0.1 = 0.09，相等，對。"}, {"type": "text", "c": "(5) 至少中 2 次 ≠ 2pₙ（後者可能超過 1），錯。故選 (1)(4)。"}]}, {"year": "112", "num": 9, "type": "多選", "rate": "46%（全對率 22%）", "img": "img/112_q09.png", "answer": [{"t": "(3)(5)"}], "key": "log₃aₖ =(3k−1)/2；交錯和在 n 偶時為負、n 奇時 =(3n+1)/4。", "kaodian": [{"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp2"}, {"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "aₖ = 3·(3√3)^(k−1)，故 log₃aₖ =(3k−1)/2。交錯和 Sₙ："}, {"type": "math", "c": "n\\text{ 偶}:\\ S_n=-\\dfrac{3n}{4}<0;\\qquad n\\text{ 奇}:\\ S_n=\\dfrac{3n+1}{4}"}, {"type": "text", "c": "要 >18 須 n 為奇數且 (3n+1)/4>18 → n>71/3 → n≥25。選項中 25、27 符合（23 太小；24、26 為偶數）。"}, {"type": "text", "c": "故選 (3)(5)。"}]}, {"year": "112", "num": 10, "type": "多選", "rate": "45%（全對率 21%）", "img": "img/112_q10.png", "answer": [{"t": "(1)(3)(5)"}], "key": "D=(0,2k) 在 OC、E=(10,8−2k) 在 AB；DE 都在長方形內須 1≤k≤3。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp1"}, {"unit": "直線與圓", "title": "考點5 平面區域與線性規劃", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp5"}], "steps": [{"type": "text", "c": "L 交左邊 OC 於 D=(0, 2k)、交右邊 AB 於 E=(10, 8−2k)，斜率 =(4−2k)/5。"}, {"type": "text", "c": "(1) k=4 代入，L 過 A(10,0)，對。(3) D 在 OC 上須 0≤2k≤6 即 0≤k≤3，對。"}, {"type": "text", "c": "DE 都在長方形內：D 在 OC（0≤k≤3）且 E 在 AB（1≤k≤4）→ 1≤k≤3，此時斜率∈[−2/5, 2/5]。"}, {"type": "math", "c": "(5)\\ \\dfrac{4-2k}{5}=\\dfrac{3}{10}\\Rightarrow k=\\dfrac54\\in[1,3]\\Rightarrow \\text{斜率 }\\tfrac{3}{10}\\text{ 可能（對）}"}, {"type": "text", "c": "(2) L 過 C 時 k=3、斜率 −2/5≠−5/2 錯；(4) k=1/2 時 E=(10,7) 在長方形外 錯。故選 (1)(3)(5)。（見右圖）"}], "fig": "img/112_fig_q10.png"}, {"year": "112", "num": 11, "type": "多選", "rate": "38%（全對率 17%）", "img": "img/112_q11.png", "answer": [{"t": "(2)(5)"}], "key": "把四個變換矩陣寫出來直接運算比對。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp5"}], "steps": [{"type": "text", "c": "A=順轉90°=[[0,1],[−1,0]]、B=逆轉90°=[[0,−1],[1,0]]、C=對 x=y 鏡射=[[0,1],[1,0]]、D=對 x=−y 鏡射=[[0,−1],[−1,0]]。"}, {"type": "text", "c": "(2) −B=[[0,1],[−1,0]]=A，對。(1) A、C 把 (1,0) 各送到 (0,−1)、(0,1) 不同，錯。(3) 鏡射的逆是自己，D⁻¹=D≠C，錯。(4) AB=I、CD=−I 不等，錯。"}, {"type": "math", "c": "(5)\\ AC=\\begin{bmatrix}1&0\\\\0&-1\\end{bmatrix}=BD\\ (\\text{對})"}, {"type": "text", "c": "故選 (2)(5)。"}]}, {"year": "112", "num": 12, "type": "多選", "rate": "21%（全對率 6%）", "img": "img/112_q12.png", "answer": [{"t": "(1)(5)"}], "key": "先用疊合把 f 寫成 2sin(x+π/3)，對稱軸在最大/最小處。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp4"}, {"unit": "三角", "title": "考點5 和差角與倍角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp5"}], "steps": [{"type": "math", "c": "f(x)=\\sin x+\\sqrt3\\cos x=2\\sin\\!\\left(x+\\tfrac{\\pi}{3}\\right)"}, {"type": "text", "c": "(1) x=π/6 時 f=2（最大值），是對稱軸，對。(2) 對稱軸有的在最大(f=2)、有的在最小(f=−2)，f(a) 不一定 = f(b)，錯。"}, {"type": "text", "c": "(3) f(x)=√3 → sin(x+π/3)=√3/2，在 [0,2π) 有 2 個解（x=0, π/3）不是 1 個，錯。"}, {"type": "text", "c": "(4) f(x)=1/2 的兩解之和 = 7π/3 > 2π，錯。(5) 4sin²(x/2)=2−2cosx（振幅 2 的餘弦），平移可得 f，對。故選 (1)(5)。"}]}, {"year": "112", "num": 13, "type": "選填", "rate": "87%", "img": "img/112_q13.png", "answer": [{"t": "選填　咖啡 "}, {"m": "80"}, {"t": " 元"}], "key": "三元一次方程組；取「第1天 − 2×第2天」直接消去，解出咖啡價。", "kaodian": [{"unit": "矩陣", "title": "考點4 一次聯立方程式與高斯消去法", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp4"}], "steps": [{"type": "text", "c": "設果汁 x、奶茶 y、咖啡 z 元，列出三天的三個方程式。取（第1天）−2×（第2天）："}, {"type": "math", "c": "(60x{+}80y{+}50z)-2(30x{+}40y{+}30z)=12900-2(6850)\\Rightarrow -10z=-800"}, {"type": "text", "c": "得 z=80，故咖啡每杯 80 元。"}]}, {"year": "112", "num": 14, "type": "選填", "rate": "67%", "img": "img/112_q14.png", "answer": [{"t": "選填　"}, {"m": "(a,b)=(3,-9)"}], "key": "兩者同為二次 → 商是常數 a；算出餘式，令 x 項係數 0、常數項 6。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp1"}], "steps": [{"type": "text", "c": "兩者皆二次，商為常數 a。餘式 = 原式 − a·(除式)："}, {"type": "math", "c": "\\text{餘式}=(a^2+b)x+(2a^2-12)"}, {"type": "text", "c": "令 x 係數 = 0、常數 = 6：a²+b=0 且 2a²−12=6 → a²=9 → a=3（a>0）、b=−9。"}, {"type": "math", "c": "(a,b)=(3,\\ -9)"}]}, {"year": "112", "num": 15, "type": "選填", "rate": "25%", "img": "img/112_q15.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{OB}{OA}=\\dfrac34"}], "key": "設 OA、OB 為垂直坐標軸；由 3AD=8BD 求 D，再用 OC⊥OD。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp2"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "設 OA=(p,0)、OB=(0,q)（垂直）。則 OC=(3p/5, 2q/5)。由 3(D−A)=8(D−B) 解得 D=(−3p/5, 8q/5)。"}, {"type": "text", "c": "OC⊥OD → OC·OD=0："}, {"type": "math", "c": "-\\dfrac{9p^2}{25}+\\dfrac{16q^2}{25}=0\\Rightarrow \\dfrac{q^2}{p^2}=\\dfrac{9}{16}\\Rightarrow \\dfrac{OB}{OA}=\\dfrac{q}{p}=\\dfrac34"}]}, {"year": "112", "num": 16, "type": "選填", "rate": "24%", "img": "img/112_q16.png", "answer": [{"t": "選填　"}, {"m": "2\\sqrt2"}], "key": "P 的投影點與 A、B、C 等距 → 投影點是 △ABC 的外心；再算 P 到 E 的距離。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp4"}, {"unit": "空間向量", "title": "考點1 空間坐標、距離與正立方體", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp1"}], "steps": [{"type": "text", "c": "P 在 E 上的投影點與 A、B、C 等距 → 該投影點是 △ABC 的外心，解得外心 = (−1,−4,3)。"}, {"type": "text", "c": "P 在 z=1 上、沿法向量 (1,0,1) 投影到外心，得 P=(−3,−4,1)。點到平面 E 的距離："}, {"type": "math", "c": "d=\\dfrac{|x+z-2|}{\\sqrt2}=\\dfrac{|-3+1-2|}{\\sqrt2}=\\dfrac{4}{\\sqrt2}=2\\sqrt2"}]}, {"year": "112", "num": 17, "type": "選填", "rate": "10%", "img": "img/112_q17.png", "answer": [{"t": "選填　"}, {"m": "\\overline{PQ}=5\\sqrt2"}], "key": "L3 是兩線的公垂線；P、Q 到 L3 的位移都垂直 L3 方向，配畢氏定理。", "kaodian": [{"unit": "空間向量", "title": "考點5 空間中的直線、軌跡與歪斜線", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp5"}, {"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp3"}], "steps": [{"type": "text", "c": "L1、L2 方向 (1,−1,1)、(2,1,−1) 互相垂直。兩線的公垂線段長 MN=4√2（M、N 為垂足）。"}, {"type": "text", "c": "P 在 L1、Q 在 L2，到公垂線 L3 距離皆 3；因 P−M、Q−N 都垂直 L3 方向，故 |PM|=|QN|=3，且 MN 垂直於兩方向："}, {"type": "math", "c": "\\overline{PQ}^{\\,2}=\\overline{MN}^{\\,2}+(|PM|^2+|QN|^2)=32+(9+9)=50\\Rightarrow \\overline{PQ}=5\\sqrt2"}]}, {"year": "112", "num": 18, "type": "混合題（單選 3 分）", "rate": "56%", "img": "img/112_q18.png", "answer": [{"t": "(4)　"}, {"m": "2\\cos\\theta"}], "key": "△OAP 等腰（OA=AP=1），設 P=OP·(cosθ,sinθ)，用 |AP|=1 解出 OP。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp2"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "令 ∠AOP=θ。因 AP=OA=1，設 P=OP·(cosθ, sinθ)，由 |AP|=1（P 到 A(1,0) 距離為 1）："}, {"type": "math", "c": "(OP\\cos\\theta-1)^2+(OP\\sin\\theta)^2=1\\Rightarrow OP^2=2\\,OP\\cos\\theta\\Rightarrow OP=2\\cos\\theta"}, {"type": "text", "c": "故選 (4)。"}], "stem": "img/112_stem.png"}, {"year": "112", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/112_q19.png", "answer": [{"t": "非選　"}, {"m": "Q=\\left(-\\tfrac{36}{25},\\tfrac{48}{25}\\right)"}], "key": "sinθ=3/5→cosθ=4/5；先求 P，再由 ∠POQ=90° 與 OQ=4sinθ 求 Q。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}, {"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp1"}], "steps": [{"type": "text", "c": "cosθ=4/5，OP=2cosθ=8/5，故 P=(8/5)(4/5, 3/5)=(32/25, 24/25)。"}, {"type": "text", "c": "OQ 與 OP 垂直（∠POQ=90°）、方向 (−sinθ, cosθ)；同理在 △OBQ 得 OQ=4sinθ=12/5："}, {"type": "math", "c": "Q=\\dfrac{12}{5}\\left(-\\tfrac35,\\ \\tfrac45\\right)=\\left(-\\dfrac{36}{25},\\ \\dfrac{48}{25}\\right)"}, {"type": "text", "c": "驗證：AP=(7/25, 24/25)、BQ=(14/25, 48/25)=2·AP，得證。（與官方參考答案一致）"}], "stem": "img/112_stem.png"}, {"year": "112", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/112_q20.png", "answer": [{"t": "非選　A到BQ "}, {"m": "\\dfrac{72}{25}"}, {"t": "、面積 "}, {"m": "\\dfrac{108}{25}"}], "key": "PABQ 是 AP∥BQ 的梯形；A 到 BQ 用點到直線公式，面積 = ½(上底+下底)×高。", "kaodian": [{"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp2"}, {"unit": "平面向量", "title": "考點4 行列式與平行四邊形面積", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp4"}], "steps": [{"type": "text", "c": "由第 19 題，AP∥BQ（皆平行 (7,24)）、|AP|=1、|BQ|=2。直線 BQ 過 B(−2,0)、方向 (7,24)，即 24x−7y+48=0："}, {"type": "math", "c": "d(A,BQ)=\\dfrac{|24(1)-0+48|}{\\sqrt{24^2+7^2}}=\\dfrac{72}{25}"}, {"type": "text", "c": "四邊形 PABQ 是上底 1、下底 2、高 72/25 的梯形："}, {"type": "math", "c": "\\text{面積}=\\dfrac12(1+2)\\cdot\\dfrac{72}{25}=\\dfrac{108}{25}"}, {"type": "text", "c": "故 A 到直線 BQ 距離 = 72/25、四邊形 PABQ 面積 = 108/25。（與官方一致）"}], "stem": "img/112_stem.png"}, {"year": "113", "num": 1, "type": "單選", "rate": "89%", "img": "img/113_q01.png", "answer": [{"t": "(2)"}], "key": "「2 小時剩一半」＝半衰期 2 小時，故 t 小時後剩 (1/2)^(t/2)。", "kaodian": [{"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp5"}, {"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp1"}], "steps": [{"type": "text", "c": "藥量每 2 小時變成一半，所以 t 小時後剩下 (1/2)^(t/2) 倍。"}, {"type": "math", "c": "4\\text{ 小時}:\\ \\left(\\tfrac12\\right)^{4/2}=\\left(\\tfrac12\\right)^{2}=\\dfrac14"}, {"type": "text", "c": "其餘：3 小時剩 √2/4、6 小時剩 1/8、8 小時剩 1/16、10 小時剩 1/32，都不符。"}, {"type": "text", "c": "只有「4 小時後剩 1/4」正確，選 (2)。"}]}, {"year": "113", "num": 2, "type": "單選", "rate": "57%", "img": "img/113_q02.png", "answer": [{"t": "(5)　"}, {"m": "\\vec{OE}"}], "key": "外積垂直於相乘的兩向量；在正方體中比對哪個選項與它同方向。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp3"}, {"unit": "空間向量", "title": "考點1 空間坐標、距離與正立方體", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp1"}], "steps": [{"type": "text", "c": "設邊長 1，依圖 D 在 O 上方、E 在 A 上方…取 A=(0,1,0)、D=(0,0,1)、G=(1,0,1)。"}, {"type": "math", "c": "\\vec{AD}\\times\\vec{AG}=(0,-1,1)\\times(1,-1,1)=(0,1,1)"}, {"type": "text", "c": "逐一比對五個選項，只有 OE = E−O = (0,1,1) 與它平行。故選 (5)。"}]}, {"year": "113", "num": 3, "type": "單選", "rate": "31%", "img": "img/113_q03.png", "answer": [{"t": "(1)　1 個"}], "key": "三根成等差 −7, −7+a, −7+2a，寫出 f 後看 f(0) 的正負。", "kaodian": [{"unit": "多項式函數", "title": "考點4 高次方程式：有理根、勘根定理與奇偶函數", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp4"}, {"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp1"}], "steps": [{"type": "text", "c": "三根為 −7、−7+a、−7+2a，最高次係數 a，故："}, {"type": "math", "c": "f(x)=a(x+7)(x+7-a)(x+7-2a)\\Rightarrow f(0)=a\\cdot 7\\cdot(7-a)(7-2a)"}, {"type": "text", "c": "逐一代 a∈{−6,−4,−2,2,4,6}：只有 a=2 時 f(0)=2·7·5·3>0，其餘皆 <0。"}, {"type": "text", "c": "故只有 1 個 a 使 f(0)>0，選 (1)。"}]}, {"year": "113", "num": 4, "type": "單選", "rate": "39%", "img": "img/113_q04.png", "answer": [{"t": "(2)　2 個"}], "key": "把式子整理成 sin(x+π/6)−sin x = 1/2，用和差化積變成一個 cos = 定值。", "kaodian": [{"unit": "三角", "title": "考點5 和差角與倍角（解方程與不等式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp5"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "原式即 sin(x+π/6)−sin x = sin(π/6)=1/2。左邊用和差化積："}, {"type": "math", "c": "2\\cos\\!\\left(x+\\tfrac{\\pi}{12}\\right)\\sin\\tfrac{\\pi}{12}=\\tfrac12\\Rightarrow \\cos\\!\\left(x+\\tfrac{\\pi}{12}\\right)=\\dfrac{1}{4\\sin\\frac{\\pi}{12}}"}, {"type": "text", "c": "右邊是介於 0 與 1 的定值，在 0≤x<2π 內 cos 等於此值恰有 2 個解（x=0 與 x=11π/6）。選 (2)。"}]}, {"year": "113", "num": 5, "type": "單選", "rate": "35%", "img": "img/113_q05.png", "answer": [{"t": "(4)　"}, {"m": "\\left(\\binom{24}{12}\\right)^2"}], "key": "中位數是第 13 個數；兩中位數差 1 只能是 25、26，前後各分 12 個。", "kaodian": [{"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp1"}, {"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp2"}], "steps": [{"type": "text", "c": "每組 25 個，中位數是第 13 小。設甲中位數 m、乙中位數 m+1。"}, {"type": "text", "c": "小於 m 的數要 12 個給甲、12 個給乙 → 共 24 個 → m−1=24 → m=25、乙中位數 26。"}, {"type": "text", "c": "於是 1~24（24 個）選 12 個給甲、27~50（24 個）選 12 個給甲，25→甲、26→乙固定："}, {"type": "math", "c": "\\binom{24}{12}\\times\\binom{24}{12}=\\left(\\binom{24}{12}\\right)^2"}, {"type": "text", "c": "故選 (4)。"}]}, {"year": "113", "num": 6, "type": "單選", "rate": "44%", "img": "img/113_q06.png", "answer": [{"t": "(3)　5 公里"}], "key": "由對稱得 AP=BP 求 cosθ；再用半角公式算 cos(θ/2)，代距離公式。", "kaodian": [{"unit": "三角", "title": "考點3 三角測量與平面幾何應用", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp3"}, {"unit": "三角", "title": "考點5 和差角與倍角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp5"}], "steps": [{"type": "text", "c": "設 B 為原點、A=(7,0)。A、B 對稱地命中 P，得 AP=BP=7/(2cosθ)=9 → cosθ=7/18。"}, {"type": "text", "c": "用半角：2cos²(θ/2)−1=7/18 → cos(θ/2)=5/6。A 改射西偏北 θ/2、AQ=9，故 Q=(7−9cos(θ/2), 9sin(θ/2))："}, {"type": "math", "c": "\\overline{BQ}=\\sqrt{\\left(7-9\\cos\\tfrac{\\theta}{2}\\right)^2+\\left(9\\sin\\tfrac{\\theta}{2}\\right)^2}=\\sqrt{130-126\\cos\\tfrac{\\theta}{2}}=\\sqrt{130-105}=5"}, {"type": "text", "c": "故 BQ=5 公里，選 (3)。"}]}, {"year": "113", "num": 7, "type": "多選", "rate": "47%（全對率 8%）", "img": "img/113_q07.png", "answer": [{"t": "(3)(4)"}], "key": "化簡後比對「定義域」是否與 y=log x（x>0）完全一樣。", "kaodian": [{"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp2"}, {"unit": "指數與對數", "title": "考點4 指數與對數函數的圖形", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp4"}], "steps": [{"type": "text", "c": "(1) y=log(5x)−1/2=log x+(log5−1/2)，因 log5−1/2≠0 → 整條上下平移，不同，錯。"}, {"type": "text", "c": "(2) 2y=log(x²) → y=log|x|，多了 x<0 的分支 → 不同，錯。"}, {"type": "text", "c": "(3) 3y=log(x³)：需 x>0，且 (1/3)·3log x=log x → 完全相同，對。"}, {"type": "text", "c": "(4) x=10^y 即 y=log x → 同一條曲線，對。"}, {"type": "math", "c": "(5)\\ x^3=10^{(y^3)}\\Rightarrow 3\\log x=y^3\\Rightarrow y=\\sqrt[3]{3\\log x}\\neq \\log x\\ (\\text{錯})"}, {"type": "text", "c": "故選 (3)(4)。"}]}, {"year": "113", "num": 8, "type": "多選", "rate": "66%（全對率 43%）", "img": "img/113_q08.png", "answer": [{"t": "(2)(3)"}], "key": "最大角看餘弦定理；周長是等差；面積用海龍公式判斷遞增。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp2"}, {"unit": "三角", "title": "考點6 三角形面積比、相似與角平分線", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp6"}], "steps": [{"type": "text", "c": "(1) 最大邊 n+2 對的角由 n²+(n+1)²−(n+2)²=(n−3)(n+1) 判斷：n=2 鈍角、n=3 直角，不全銳角，錯。"}, {"type": "text", "c": "(2) 周長 = 3n+3，每次加 3 → 等差，對。"}, {"type": "math", "c": "(3)\\ \\text{面積}=\\tfrac14(n+1)\\sqrt{3(n+3)(n-1)}\\ \\text{隨 }n\\text{ 遞增（對）}"}, {"type": "text", "c": "(4) T₅(5,6,7) 三高 = 2A/5, 2A/6, 2A/7，比 1/5,1/6,1/7 不成等差，錯。"}, {"type": "text", "c": "(5) 邊越接近正三角形最大角越小：T₃ 最大角 90° < T₂ 最大角(≈104.5°)，錯。故選 (2)(3)。"}]}, {"year": "113", "num": 9, "type": "多選", "rate": "36%（全對率 12%）", "img": "img/113_q09.png", "answer": [{"t": "(3)"}], "key": "迴歸線過 (x̄,ȳ) 求平均；斜率 = r·(σ_y/σ_x) 反推體重標準差。", "kaodian": [{"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp3"}, {"unit": "數據分析", "title": "考點2 相關係數 r", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp2"}], "steps": [{"type": "text", "c": "迴歸線過 (x̄,ȳ)：ȳ_A=2(5.2)−0.6=9.8、ȳ_B=1.5(6)+0.4=9.4，故 (1) ȳ_A<ȳ_B 錯。"}, {"type": "text", "c": "斜率=r·(σ_y/σ_x)：A 得 σ_yA=1、B 得 σ_yB=0.5，σ_yA>σ_yB，(2) 錯。"}, {"type": "math", "c": "(3)\\ |8.6-\\overline{y_A}|=|8.6-9.8|=1.2>1=\\sigma_{yA}\\ (\\text{對})"}, {"type": "text", "c": "(4) P 到 L_A 距離 2/√5≈0.89 > 到 L_B 距離 ≈0.11，錯。"}, {"type": "text", "c": "(5) P 到 A 中心 √1.6 > 到 B 中心 √0.8，錯。故只選 (3)。"}]}, {"year": "113", "num": 10, "type": "多選", "rate": "45%（全對率 23%）", "img": "img/113_q10.png", "answer": [{"t": "(3)(5)"}], "key": "P 到 x 軸距離 2√3 = 正六邊形的邊心距 → 邊長 4；再逐一算向量與斜率。", "kaodian": [{"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp2"}, {"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp1"}], "steps": [{"type": "text", "c": "正方形邊 6、一邊在 x 軸上 → 中心 A 高 3。正六邊形右頂點高 = 邊心距 (s√3)/2 = 2√3 → 邊長 s=4，且 P 為六邊形右頂點落在正方形左邊上。"}, {"type": "math", "c": "\\vec{BA}=(a_x-b_x,\\ 3-2\\sqrt3)=(7,\\ 3-2\\sqrt3)\\ ((3)\\ \\text{對})"}, {"type": "text", "c": "(1) A 高 3 < B 高 2√3≈3.46，錯。(2) 六邊形邊長為 4 不是 6，錯。"}, {"type": "math", "c": "(4)\\ \\overline{AP}=\\sqrt{30-12\\sqrt3}\\approx3.04<\\sqrt{10}\\ (\\text{錯});\\ (5)\\ \\text{斜率}=\\dfrac{2\\sqrt3-3}{-3}\\approx-0.15>-\\tfrac{1}{\\sqrt3}\\ (\\text{對})"}, {"type": "text", "c": "故選 (3)(5)。（見右圖）"}], "fig": "img/113_fig_q10.png"}, {"year": "113", "num": 11, "type": "多選", "rate": "43%（全對率 25%）", "img": "img/113_q11.png", "answer": [{"t": "(2)(3)"}], "key": "行列式 ab−6 判斷解的個數；把 12 種等可能 (a,b) 分類數機率。", "kaodian": [{"unit": "矩陣", "title": "考點4 一次聯立方程式與高斯消去法", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp4"}, {"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp4"}], "steps": [{"type": "text", "c": "係數行列式 = ab−6。≠0 有唯一解；=0 時 (a,b)=(6,1) 無限多解、(3,2) 無解。共 6×2=12 種等可能。"}, {"type": "text", "c": "(2) 無解只有 (3,2) → 1/12，對。(3) 唯一解 = 12−2=10 種 → 5/6，對。"}, {"type": "text", "c": "(1) a=b 只有 (1,1),(2,2) → 2/12=1/6≠1/3，錯。(4) 反面(b=2)且有解 = a≠3 共 5 種 → 5/12≠1/2，錯。"}, {"type": "math", "c": "(5)\\ x=\\dfrac{3}{a-3},\\ x>0\\Leftrightarrow a>3\\Rightarrow P=\\dfrac{3}{5}\\neq\\dfrac{2}{5}\\ (\\text{錯})"}, {"type": "text", "c": "故選 (2)(3)。"}]}, {"year": "113", "num": 12, "type": "多選", "rate": "36%（全對率 11%）", "img": "img/113_q12.png", "answer": [{"t": "(2)(4)(5)"}], "key": "T 的行列式 = 3 固定 → 面積固定；可逆 → 有原像；不變點在 x=0。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp5"}, {"unit": "矩陣", "title": "考點1 矩陣的意義、相等與乘法", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp1"}], "steps": [{"type": "text", "c": "T(x,y)=(3x, ax+y)。A(1,0)→(3,a)、B(0,1)→(0,1)、C(−1,0)→(−3,−a)。"}, {"type": "text", "c": "(1) a=0 得三角形 (3,0),(0,1),(−3,0)，等腰但非直角，錯。"}, {"type": "text", "c": "(2) 不變點須 3x=x → x=0；△ABC 上有 B(0,1) 及 (0,0)（邊 AC 上）兩點不動 → 對。"}, {"type": "text", "c": "(3) a>0 時圖形在 x>0 的部分 y>0，不進第四象限 →「必有」錯。"}, {"type": "math", "c": "(4)\\ \\det T=3\\neq0\\ \\text{可逆}\\Rightarrow \\Omega=T^{-1}(\\triangle ABC)\\ \\text{存在（對）};\\quad (5)\\ \\text{面積}=|\\det T|\\times1=3\\ \\text{（定值，對）}"}, {"type": "text", "c": "故選 (2)(4)(5)。"}]}, {"year": "113", "num": 13, "type": "選填", "rate": "67%", "img": "img/113_q13.png", "answer": [{"t": "選填　"}, {"m": "A:B:C=2:3:5"}], "key": "用兩個加權平均列式解出比例。", "kaodian": [{"unit": "數據分析", "title": "考點4 加權平均、中位數與資料判讀", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp4"}], "steps": [{"type": "text", "c": "甲乙平均 280：(100A+400B)/(A+B)=280 → 120B=180A → A:B=2:3。設 A=2k、B=3k。"}, {"type": "text", "c": "三型平均 260：100A+400B+240C=260(A+B+C)，代入得 100k=20C → C=5k。"}, {"type": "math", "c": "A:B:C=2k:3k:5k=2:3:5"}, {"type": "text", "c": "故比為 2:3:5。"}]}, {"year": "113", "num": 14, "type": "選填", "rate": "38%", "img": "img/113_q14.png", "answer": [{"t": "選填　"}, {"m": "a=-3,\\ b=3"}], "key": "用 x²≡2x−3 把每一項降次，湊出係數全為 0。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp1"}], "steps": [{"type": "text", "c": "餘式：f≡x+1、g≡x−3、h≡−2；又 x²≡2x−3（mod x²−2x+3）。"}, {"type": "math", "c": "xf(x)\\equiv x(x+1)=x^2+x\\equiv(2x-3)+x=3x-3"}, {"type": "text", "c": "故 xf+ag+bh ≡ (3+a)x+(−3−3a−2b)。要被整除須係數皆 0："}, {"type": "math", "c": "3+a=0,\\ -3-3a-2b=0\\Rightarrow a=-3,\\ b=3"}, {"type": "text", "c": "故 a=−3、b=3。"}]}, {"year": "113", "num": 15, "type": "選填", "rate": "48%", "img": "img/113_q15.png", "answer": [{"t": "選填　"}, {"m": "25"}], "key": "中獎率 0.4% 反推球數 2500；算第 101 人抽到「剩餘幸運球」的期望。", "kaodian": [{"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp6"}, {"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp3"}], "steps": [{"type": "text", "c": "中獎機率 10/N=0.4% → N=2500 顆球（10 顆幸運）。前 100 人已抽走 1 顆 5000、0 顆 8000。"}, {"type": "text", "c": "剩 2500−100=2400 顆，其中 5000 券 4 顆、8000 券 5 顆。第 101 人抽 1 顆："}, {"type": "math", "c": "E=5000\\cdot\\dfrac{4}{2400}+8000\\cdot\\dfrac{5}{2400}=\\dfrac{60000}{2400}=25"}, {"type": "text", "c": "期望值 25 元。"}]}, {"year": "113", "num": 16, "type": "選填", "rate": "8%", "img": "img/113_q16.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{2\\sqrt5}{5}"}], "key": "(2,−3) 與 (3,2) 互相垂直、長皆 √13；兩投影長是 L−1、L−2，用畢氏解 L。", "kaodian": [{"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp3"}, {"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp1"}], "steps": [{"type": "text", "c": "(2,−3)⊥(3,2)、長皆 √13。v 在兩方向的投影長分別是 L−1、L−2（L=|v|）。因兩方向垂直："}, {"type": "math", "c": "L^2=(L-1)^2+(L-2)^2\\Rightarrow L^2-6L+5=0\\Rightarrow L=5\\ (L=1\\ \\text{使投影為負，不合})"}, {"type": "text", "c": "故 v = 4·(2,−3)/√13 + 3·(3,2)/√13 = (17,−6)/√13。在 (4,7) 方向的投影長："}, {"type": "math", "c": "\\dfrac{\\vec{v}\\cdot(4,7)}{|(4,7)|}=\\dfrac{26/\\sqrt{13}}{\\sqrt{65}}=\\dfrac{2}{\\sqrt5}=\\dfrac{2\\sqrt5}{5}"}]}, {"year": "113", "num": 17, "type": "選填", "rate": "5%", "img": "img/113_q17.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{1}{3}"}], "key": "「到 P 距離 |x−y| 的所有點」是一個圓；圓要落在正方形內，等於「半徑 ≤ P 到四邊的最短距離」。", "kaodian": [{"unit": "直線與圓", "title": "考點5 平面區域與線性規劃", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp5"}, {"unit": "數與式", "title": "考點2 絕對值的意義、方程式與不等式", "url": "https://mathmap-kitty.github.io/web/115學測數學_數與式.html#kp2"}], "steps": [{"type": "text", "c": "到 P 距離 |x−y| 的所有點 = 以 P 為圓心、半徑 r=|x−y| 的圓。圓落在正方形內，就是要："}, {"type": "math", "c": "|x-y|\\le \\min(x,\\,1-x,\\,y,\\,1-y)"}, {"type": "text", "c": "在 x≥y 的一半，條件化為 x/2≤y≤x 且 y≥2x−1，積分得面積 1/6；由 x、y 對稱，另一半也 1/6。"}, {"type": "math", "c": "\\text{面積}=2\\times\\dfrac16=\\dfrac13"}, {"type": "text", "c": "故區域 R 面積 = 1/3。（見右圖）"}], "fig": "img/113_fig_q17.png"}, {"year": "113", "num": 18, "type": "混合題（單選 3 分）", "rate": "64%", "img": "img/113_q18.png", "answer": [{"t": "(4)　"}, {"m": "\\dfrac{\\sqrt2}{2}"}], "key": "投影點沿法向量方向；求 OQ 與 x 軸的夾角餘弦。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp4"}, {"unit": "空間向量", "title": "考點2 空間向量的內積、夾角與垂直", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp2"}], "steps": [{"type": "text", "c": "E: x−z=4，法向量 (1,0,−1)。O 沿法向量投影到 E：Q=(t,0,−t)，代入 x−z=4 → 2t=4 → Q=(2,0,−2)。"}, {"type": "math", "c": "\\cos\\alpha=\\dfrac{\\vec{OQ}\\cdot(1,0,0)}{|\\vec{OQ}|}=\\dfrac{2}{\\sqrt{8}}=\\dfrac{\\sqrt2}{2}"}, {"type": "text", "c": "故選 (4)。"}], "stem": "img/113_stem.png"}, {"year": "113", "num": 19, "type": "非選擇題（4 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/113_q19.png", "answer": [{"t": "非選　"}, {"m": "a^2\\ge 3(b^2+c^2)"}], "key": "θ≤π/6 使 cosθ≥√3/2，兩邊為正平方後整理。", "kaodian": [{"unit": "空間向量", "title": "考點2 空間向量的內積、夾角與垂直", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp2"}, {"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp4"}], "steps": [{"type": "text", "c": "OP=(a,b,c) 與 (1,0,0) 夾角 θ≤π/6，cos 在 [0,π/2] 遞減，故："}, {"type": "math", "c": "\\cos\\theta=\\dfrac{a}{\\sqrt{a^2+b^2+c^2}}\\ge\\cos\\dfrac{\\pi}{6}=\\dfrac{\\sqrt3}{2}"}, {"type": "text", "c": "兩邊為正，平方：a²/(a²+b²+c²)≥3/4 → 4a²≥3(a²+b²+c²)，整理得"}, {"type": "math", "c": "a^2\\ge 3(b^2+c^2)"}, {"type": "text", "c": "得證。（與官方參考答案一致）"}], "stem": "img/113_stem.png"}, {"year": "113", "num": 20, "type": "非選擇題（8 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/113_q20.png", "answer": [{"t": "非選　"}, {"m": "2-2\\sqrt3\\le c\\le 2+2\\sqrt3"}, {"t": "、最小 "}, {"m": "\\overline{OP}=4\\sqrt3-4"}], "key": "在 E 上 a−c=4、b=0 代入不等式解 c 範圍；OP 配方求最小。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp4"}, {"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp2"}], "steps": [{"type": "text", "c": "P 在 E 上 → a−c=4（a=c+4）、b=0。代入 a²≥3(b²+c²)=3c²："}, {"type": "math", "c": "(c+4)^2\\ge 3c^2\\Rightarrow c^2-4c-8\\le0\\Rightarrow 2-2\\sqrt3\\le c\\le 2+2\\sqrt3"}, {"type": "text", "c": "這就是 c 的可能範圍。再看 OP 長度："}, {"type": "math", "c": "\\overline{OP}=\\sqrt{a^2+c^2}=\\sqrt{(c+4)^2+c^2}=\\sqrt{2(c+2)^2+8}"}, {"type": "text", "c": "拋物線頂點 c=−2 不在範圍內，故最小發生在左端 c=2−2√3："}, {"type": "math", "c": "\\overline{OP}_{\\min}=\\sqrt{64-32\\sqrt3}=4\\sqrt3-4"}, {"type": "text", "c": "故 c∈[2−2√3, 2+2√3]、OP 最小長度 = 4√3−4 = 4(√3−1)。（與官方一致）"}], "stem": "img/113_stem.png"}, {"year": "114", "num": 1, "type": "單選", "rate": "57%", "img": "img/114_q01.png", "answer": [{"t": "(5)　"}, {"m": "k=6"}], "key": "「獨立」代表 P(藍 且 1號)=P(藍)×P(1號)，列式解 k。", "kaodian": [{"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp5"}, {"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp3"}], "steps": [{"type": "text", "c": "球總數 = 藍(2+3) + 綠(4+k) = 9+k。其中藍球 5 顆、1 號球 (2+4)=6 顆、又藍又 1 號的 2 顆。"}, {"type": "text", "c": "兩事件獨立，機率相乘："}, {"type": "math", "c": "\\dfrac{2}{9+k}=\\dfrac{5}{9+k}\\times\\dfrac{6}{9+k}"}, {"type": "text", "c": "兩邊乘 (9+k)²：2(9+k)=30 → 9+k=15 → k=6。選 (5)。"}]}, {"year": "114", "num": 2, "type": "單選", "rate": "62%", "img": "img/114_q02.png", "answer": [{"t": "(2)　6"}], "key": "直線與兩軸圍成的直角三角形，兩股是 x 截距與 y 截距；面積差列方程。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp1"}, {"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp2"}], "steps": [{"type": "text", "c": "L1、L2 都過 x 軸上的 P(a,0)，與兩軸圍成直角三角形。一股是 a，另一股是 y 截距。"}, {"type": "text", "c": "L1 斜率 -4/3：y 截距 4a/3，面積 = ½·a·(4a/3)=2a²/3。"}, {"type": "text", "c": "L2 斜率 -3/2：y 截距 3a/2，面積 = ½·a·(3a/2)=3a²/4。"}, {"type": "math", "c": "\\left|\\dfrac{2a^2}{3}-\\dfrac{3a^2}{4}\\right|=\\dfrac{a^2}{12}=3\\Rightarrow a^2=36\\Rightarrow a=6"}, {"type": "text", "c": "故 a=6，選 (2)。"}]}, {"year": "114", "num": 3, "type": "單選", "rate": "60%", "img": "img/114_q03.png", "answer": [{"t": "(4)　"}, {"m": "4\\times 5!\\times 4!\\times 3!"}], "key": "三類各自「捆綁」→ 內部排列 × 三捆的排列，再扣掉不合規定者。", "kaodian": [{"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "同類綁在一起，內部各自排列：鋼琴 5!、小提琴 4!、歌唱 3!。"}, {"type": "text", "c": "三個「捆包」排成一列共 3!=6 種。限制：歌唱要在鋼琴之後或小提琴之後，也就是歌唱「不能排最前面」。"}, {"type": "text", "c": "歌唱排最前面的有 2 種（歌–鋼–提、歌–提–鋼），扣掉後剩 6−2=4 種捆包排法。"}, {"type": "math", "c": "4\\times 5!\\times 4!\\times 3!"}, {"type": "text", "c": "故選 (4)。"}]}, {"year": "114", "num": 4, "type": "單選", "rate": "44%", "img": "img/114_q04.png", "answer": [{"t": "(3)　90"}], "key": "對每個整數 x，數「曲線 y=log₂x 下方、x 軸上方」的整數 y 有幾個，再相加。", "kaodian": [{"unit": "指數與對數", "title": "考點4 指數與對數函數的圖形", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp4"}, {"unit": "指數與對數", "title": "考點3 常用對數：科學記號、位數與首位", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp3"}], "steps": [{"type": "text", "c": "區域由 y=log₂x、x 軸、x=61/2(=30.5) 圍成。內部格子點：整數 x 由 2 到 30，對每個 x 數 1≤y<log₂x 的整數 y。"}, {"type": "text", "c": "x=17~30 時 log₂x 在 4~5 間各 4 個；x=9~16 各 3 個；x=5~8 各 2 個；x=3,4 各 1 個；x=2 為 0 個。"}, {"type": "math", "c": "2\\times 1+4\\times 2+8\\times 3+14\\times 4=2+8+24+56=90"}, {"type": "text", "c": "共 90 個，選 (3)。（見右圖）"}], "fig": "img/114_fig_q04.png"}, {"year": "114", "num": 5, "type": "單選", "rate": "30%", "img": "img/114_q05.png", "answer": [{"t": "(1)　"}, {"m": "\\dfrac{1}{3}"}], "key": "用倍角公式把兩個不等式各自因式分解，再取交集。", "kaodian": [{"unit": "三角", "title": "考點5 和差角與倍角（解方程與不等式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp5"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "sin2θ>sinθ：2sinθcosθ−sinθ>0 → sinθ(2cosθ−1)>0。"}, {"type": "text", "c": "cos2θ>cosθ：2cos²θ−cosθ−1>0 →(2cosθ+1)(cosθ−1)>0。因 cosθ−1≤0，需 cosθ<−1/2，得 θ∈(2π/3, 4π/3)。"}, {"type": "text", "c": "在此範圍 2cosθ−1<0，故第一式需 sinθ<0，即 θ∈(π, 2π)。取交集："}, {"type": "math", "c": "\\left(\\dfrac{2\\pi}{3},\\dfrac{4\\pi}{3}\\right)\\cap(\\pi,2\\pi)=\\left(\\pi,\\dfrac{4\\pi}{3}\\right)"}, {"type": "text", "c": "寫成 aπ<θ<bπ 即 a=1、b=4/3，b−a=1/3。選 (1)。"}]}, {"year": "114", "num": 6, "type": "單選", "rate": "35%", "img": "img/114_q06.png", "answer": [{"t": "(3)　"}, {"m": "2\\sqrt{10}"}], "key": "兩兩垂直 → 體積=|u||v||w|；用內積把長度一個個湊出來。", "kaodian": [{"unit": "空間向量", "title": "考點2 空間向量的內積、夾角與垂直", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp2"}, {"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp3"}], "steps": [{"type": "text", "c": "u,v,w 兩兩垂直（內積 0）。因此 |u−v|²=|u|²+|v|²，|v−w|²=|v|²+|w|²："}, {"type": "math", "c": "|\\vec{u}-\\vec{v}|^2=4+1+0=5,\\qquad |\\vec{v}-\\vec{w}|^2=1+4+9=14"}, {"type": "text", "c": "再算 (u−v)·(v−w)，展開後因垂直只剩 −|v|²："}, {"type": "math", "c": "(\\vec{u}-\\vec{v})\\cdot(\\vec{v}-\\vec{w})=(2)(-1)+(-1)(2)+0=-4=-|\\vec{v}|^2\\Rightarrow |\\vec{v}|^2=4"}, {"type": "text", "c": "於是 |u|²=5−4=1、|w|²=14−4=10。體積 = √1·√4·√10 = 2√10，選 (3)。"}]}, {"year": "114", "num": 7, "type": "多選", "rate": "66%（全對率 44%）", "img": "img/114_q07.png", "answer": [{"t": "(2)(4)"}], "key": "算出 b_n 的遞迴，會發現它是公比 1/3 的等比數列。", "kaodian": [{"unit": "數列與級數", "title": "考點3 遞迴數列：構造等比與數學歸納法", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp3"}, {"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp2"}], "steps": [{"type": "text", "c": "由 3a_{n+1}=a_n+n、a_1=2 得 a_2=1，故 (1) a_2=2 錯。"}, {"type": "text", "c": "b_n=a_n−n/2+3/4，算得 b_1=9/4、b_2=3/4，(2) 對。代入化簡得遞迴："}, {"type": "math", "c": "b_{n+1}=\\dfrac{1}{3}b_n\\ \\Rightarrow\\ b_n=\\dfrac{9}{4}\\left(\\dfrac{1}{3}\\right)^{n-1}"}, {"type": "text", "c": "公比是 1/3 不是 2/3，(3) 錯。"}, {"type": "math", "c": "(5)\\ b_{10}=\\dfrac{9}{4}\\cdot\\dfrac{1}{3^{9}}=\\dfrac{1}{8748}\\approx 1.14\\times10^{-4}>10^{-4}\\ (\\text{錯})"}, {"type": "text", "c": "(4) 由 a_n=b_n+n/2−3/4 代入，3ⁿa_n=[27+3ⁿ(2n−3)]/4 恆為正整數，對。故選 (2)(4)。"}]}, {"year": "114", "num": 8, "type": "多選", "rate": "48%（全對率 25%）", "img": "img/114_q08.png", "answer": [{"t": "(3)(5)"}], "key": "兩邊化成同底 2 的次方，指數相等後整理成一個圓。", "kaodian": [{"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp1"}, {"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp3"}], "steps": [{"type": "math", "c": "\\dfrac{2^{x^2}}{8}=\\dfrac{4^{x}}{2^{y^2}}\\Rightarrow 2^{x^2-3}=2^{2x-y^2}\\Rightarrow x^2-3=2x-y^2"}, {"type": "math", "c": "(x-1)^2+y^2=4\\quad(\\text{圓心 }(1,0)\\text{、半徑 }2)"}, {"type": "text", "c": "(3) 圖形是圓，對。(1) x=3 代入得 y=0 只有 1 解，錯。(2) 圓心不在原點，對 (−a,−b) 不對稱，錯。"}, {"type": "text", "c": "(4) 圓心到 x+y=4 的距離 = 3/√2 ≈ 2.12 > 2，直線與圓不相交，錯。"}, {"type": "math", "c": "(5)\\ x-y=(1+2\\cos\\theta)-2\\sin\\theta\\le 1+2\\sqrt{2}\\ (\\text{對})"}, {"type": "text", "c": "故選 (3)(5)。"}]}, {"year": "114", "num": 9, "type": "多選", "rate": "44%（全對率 20%）", "img": "img/114_q09.png", "answer": [{"t": "(2)(4)(5)"}], "key": "「有沒有實根」看判別式：≥0 有、<0 沒有。", "kaodian": [{"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp2"}, {"unit": "多項式函數", "title": "考點3 多項式方程式與不等式的解法", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp3"}], "steps": [{"type": "text", "c": "有實根：b²−4c≥0；沒實根：(b+2)²−4c<0。兩式相減：(b+2)²−b²<0 → 4b+4<0 → b<−1，(2) 對。"}, {"type": "text", "c": "又 4c>(b+2)²≥0 → c>0，故 (1) c<0 錯。"}, {"type": "text", "c": "(4) 判別式 (b+2)²+4c，因 c>0 一定 >0 → 有實根，對。"}, {"type": "math", "c": "(5)\\ (b-2)^2-4c\\ge (b-2)^2-b^2=4(1-b)>0\\ (\\because b<-1)\\Rightarrow \\text{有實根（對）}"}, {"type": "text", "c": "(3) 取 b=−3, c=2：(b+1)²−4c=4−8<0 無實根，故不一定成立 → 錯。故選 (2)(4)(5)。"}]}, {"year": "114", "num": 10, "type": "多選", "rate": "38%（全對率 17%）", "img": "img/114_q10.png", "answer": [{"t": "(1)(4)(5)"}], "key": "sinπx 週期 2、左右對稱；y=k(0<k<1) 在 (0,1) 與 (2,3) 各交兩點，共 4 點。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp4"}], "steps": [{"type": "text", "c": "y=sinπx 在 (0,1) 與 (2,3) 各是一個上凸的波峰。水平線 y=k（0<k<1）在兩段各交 2 點，共 4 個交點：x1,x2∈(0,1)、x3,x4∈(2,3)。"}, {"type": "text", "c": "(1) 要有 x1,x2 在 (0,1)，必須 k>0，對。(2) 交點其實有 4 個不是 3 個，錯。(3) 由對稱 x1+x2=1（對稱於 0.5），不是 <1，錯。"}, {"type": "math", "c": "(4)\\ 2\\overline{PQ}=\\overline{QR}:\\ (x_2-x_1)=2t,\\ (x_3-x_2)=2-2t\\Rightarrow t=\\tfrac13,\\ k=\\cos\\tfrac{\\pi}{3}=\\tfrac12\\ (\\text{對})"}, {"type": "math", "c": "(5)\\ x_1+x_2+x_3+x_4=1+5=6>5\\ (\\text{對})"}, {"type": "text", "c": "故選 (1)(4)(5)。（見右圖）"}], "fig": "img/114_fig_q10.png"}, {"year": "114", "num": 11, "type": "多選", "rate": "38%（全對率 17%）", "img": "img/114_q11.png", "answer": [{"t": "(3)(4)(5)"}], "key": "餘弦定理求角；用坐標定出各點，求角平分線與 CD 的交點比例。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp2"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp3"}, {"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp2"}], "steps": [{"type": "math", "c": "\\cos\\angle BAC=\\dfrac{AB^2+AC^2-BC^2}{2\\cdot AB\\cdot AC}=\\dfrac{36+25-16}{60}=\\dfrac{3}{4}\\ ((3)\\ \\text{對})"}, {"type": "text", "c": "設 A 為原點，求出 C=(15/4, 5√7/4)、D=AB 中點=(3,0)。B 的角平分線與 CD 交於 P，解得 P 分 CD 使 CP:PD=4:3。"}, {"type": "text", "c": "所以 CP=(4/7)CD（不是 3/7），(1) 錯。"}, {"type": "math", "c": "\\vec{AP}=\\dfrac{2}{7}\\vec{AB}+\\dfrac{3}{7}\\vec{AC}\\ (\\text{係數與 (2) 剛好相反，(2) 錯})"}, {"type": "math", "c": "[\\triangle ACP]=\\dfrac{15}{14}\\sqrt{7}\\ ((4)\\ \\text{對}),\\qquad \\vec{AP}\\cdot\\vec{AC}=\\dfrac{120}{7}\\ ((5)\\ \\text{對})"}, {"type": "text", "c": "故選 (3)(4)(5)。"}]}, {"year": "114", "num": 12, "type": "多選", "rate": "22%（全對率 2%）", "img": "img/114_q12.png", "answer": [{"t": "(1)(3)(4)(5)"}], "key": "u=100−x、v=y÷1000 都是直線變換；標準差看斜率絕對值，注意單位換算。", "kaodian": [{"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp3"}, {"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp1"}], "steps": [{"type": "text", "c": "甲+乙=100，故 u=100−x，(1) 對。1 微米 = 1000 奈米，所以 v(微米)=y(奈米)/1000，(2) 說 1000y 錯。"}, {"type": "text", "c": "(3) u=100−x 斜率 −1（絕對值 1），標準差不變，對。"}, {"type": "math", "c": "v=\\dfrac{21.3x-40}{1000},\\ x=100-u\\Rightarrow v=2.09-0.0213u\\Rightarrow b=2.09\\ ((4)\\ \\text{對})"}, {"type": "text", "c": "(5) 新增的點恰在迴歸線上（殘差 0），加進去不會改變最小平方線，對。故選 (1)(3)(4)(5)。"}]}, {"year": "114", "num": 13, "type": "選填", "rate": "48%", "img": "img/114_q13.png", "answer": [{"t": "選填　"}, {"m": "(-6,\\ 3)"}], "key": "用商式寫出 f；at³+bt 是奇函數，對稱中心就在平移後的原點。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp1"}, {"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp5"}], "steps": [{"type": "text", "c": "q(x) 在 x=−6 有最大值 8，故 q(x)=a(x+6)²+8（a<0）。又 f(x)=(x+6)q(x)+3："}, {"type": "math", "c": "f(x)=a(x+6)^3+8(x+6)+3"}, {"type": "text", "c": "令 t=x+6，f=at³+8t+3。at³+8t 是奇函數（對稱於 t=0），所以對稱中心在 t=0（即 x=−6），該處 f=3。"}, {"type": "math", "c": "\\text{對稱中心}=(-6,\\ 3)"}, {"type": "text", "c": "故答案 (−6, 3)。"}]}, {"year": "114", "num": 14, "type": "選填", "rate": "33%", "img": "img/114_q14.png", "answer": [{"t": "選填　"}, {"m": "a+b+c=-11"}], "key": "點到平面距離公式；用 a,b,c<0 判斷絕對值內的正負，再解聯立。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp4"}], "steps": [{"type": "text", "c": "點到平面距離 = |把點代入|/|法向量|。三平面法向量長度為 5、5、3："}, {"type": "math", "c": "\\dfrac{|4b+3c-2|}{5}=6,\\quad \\dfrac{|3b+4c+5|}{5}=6,\\quad \\dfrac{|a+2b+2c+2|}{3}=6"}, {"type": "text", "c": "因 a,b,c<0，各絕對值內為負，得 4b+3c=−28、3b+4c=−35，解出 b=−1、c=−8。"}, {"type": "math", "c": "a+2b+2c+2=a-16=-18\\Rightarrow a=-2\\Rightarrow a+b+c=-11"}, {"type": "text", "c": "故 a+b+c=−11。"}]}, {"year": "114", "num": 15, "type": "選填", "rate": "16%", "img": "img/114_q15.png", "answer": [{"t": "選填　"}, {"m": "405"}], "key": "分「第幾次才湊滿 3 個正面」四種情形算機率，再乘花費求期望值。", "kaodian": [{"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp6"}, {"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp3"}], "steps": [{"type": "text", "c": "每次正面機率 1/2。四種結果的機率："}, {"type": "math", "c": "P_{240}=\\left(\\tfrac12\\right)^3=\\tfrac18,\\quad P_{320}=\\binom{3}{2}\\tfrac1{8}\\cdot\\tfrac12=\\tfrac{3}{16},\\quad P_{400}=\\binom{4}{2}\\tfrac1{16}\\cdot\\tfrac12=\\tfrac{3}{16}"}, {"type": "math", "c": "P_{480}=P(\\text{5 次}\\le 2\\text{ 正})=\\dfrac{1+5+10}{32}=\\dfrac12"}, {"type": "math", "c": "E=240\\cdot\\tfrac18+320\\cdot\\tfrac3{16}+400\\cdot\\tfrac3{16}+480\\cdot\\tfrac12=30+60+75+240=405"}, {"type": "text", "c": "期望花費 405 元。"}]}, {"year": "114", "num": 16, "type": "選填", "rate": "18%", "img": "img/114_q16.png", "answer": [{"t": "選填　"}, {"m": "\\overline{AB}=\\dfrac{24}{5}"}], "key": "圓心到 L1 距離 1 定出 m；L2 相切定出半徑；再用弦長公式。", "kaodian": [{"unit": "直線與圓", "title": "考點4 直線與圓的位置：相切、弦長與切線", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp4"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "L1 過 (3,1) 斜率 m。圓心 O 到 L1 距離為 1："}, {"type": "math", "c": "\\dfrac{|1-3m|}{\\sqrt{m^2+1}}=1\\Rightarrow 8m^2-6m=0\\Rightarrow m=\\dfrac34\\ (m=0\\ \\text{不合})"}, {"type": "text", "c": "則 L2 斜率 −3/4，方程式 3x+4y−13=0。Γ 與 L2 相切 → 半徑 = 圓心到 L2 的距離："}, {"type": "math", "c": "r=\\dfrac{|-13|}{\\sqrt{9+16}}=\\dfrac{13}{5}"}, {"type": "math", "c": "\\overline{AB}=2\\sqrt{r^2-1}=2\\sqrt{\\dfrac{169}{25}-1}=2\\cdot\\dfrac{12}{5}=\\dfrac{24}{5}"}]}, {"year": "114", "num": 17, "type": "選填", "rate": "14%", "img": "img/114_q17.png", "answer": [{"t": "選填　"}, {"m": "\\overline{CD}=3+\\sqrt{2}"}], "key": "餘弦定理求 AC 與外接圓半徑；把弦長換成圓心角，用和角求 CD。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp2"}, {"unit": "三角", "title": "考點7 圓周角與二面角中的三角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp7"}, {"unit": "三角", "title": "考點5 和差角與倍角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp5"}], "steps": [{"type": "math", "c": "AC^2=3^2+3^2-2\\cdot3\\cdot3\\cdot\\left(-\\tfrac18\\right)=\\tfrac{81}{4}\\Rightarrow AC=\\tfrac92,\\ \\sin\\angle ABC=\\tfrac{3\\sqrt7}{8}"}, {"type": "math", "c": "2R=\\dfrac{AC}{\\sin\\angle ABC}=\\dfrac{12}{\\sqrt7}"}, {"type": "text", "c": "把弦 AB=BC=3、BD=4 都換成對應的圓心角。取滿足 AD≤CD 的一側，CD 對應的圓心角為 (α+β)，其中 sin(α/2)=√7/4、sin(β/2)=√7/3。用和角公式："}, {"type": "math", "c": "\\overline{CD}=2R\\sin\\tfrac{\\alpha+\\beta}{2}=\\dfrac{12}{\\sqrt7}\\cdot\\dfrac{\\sqrt{14}+3\\sqrt7}{12}=\\sqrt2+3"}, {"type": "text", "c": "故 CD=3+√2。"}]}, {"year": "114", "num": 18, "type": "混合題（單選 3 分）", "rate": "58%", "img": "img/114_q18.png", "answer": [{"t": "(2)　"}, {"m": "c=-1"}], "key": "旋轉矩陣角度可疊加；A² 對應旋轉 2θ，比對出角度。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp5"}, {"unit": "矩陣", "title": "考點2 矩陣的高次方 Aⁿ", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp2"}], "steps": [{"type": "text", "c": "A 是逆時針旋轉某銳角 θ 的旋轉矩陣，則 A²=旋轉 2θ。比對 A²=[[0,c],[1,d]] 與 [[cos2θ,−sin2θ],[sin2θ,cos2θ]]："}, {"type": "math", "c": "\\sin 2\\theta=1,\\ \\cos 2\\theta=0\\Rightarrow 2\\theta=90^\\circ\\Rightarrow \\theta=45^\\circ"}, {"type": "math", "c": "A^2=\\begin{bmatrix}0&-1\\\\1&0\\end{bmatrix}\\Rightarrow c=-1,\\ d=0"}, {"type": "text", "c": "故 c=−1，選 (2)。"}], "stem": "img/114_stem.png"}, {"year": "114", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/114_q19.png", "answer": [{"t": "非選　"}, {"m": "Q=(-\\sqrt2,\\,0)"}, {"t": "，夾角 60°"}], "key": "A³ 是旋轉 135°、B⁴ 是旋轉 120°；旋轉只改方向角、不改長度。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp5"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "由 A²=旋轉90° 得 A=旋轉45°；由 B³=旋轉90° 得 B=旋轉30°。P(1,1) 在方向 45°、長 √2。"}, {"type": "math", "c": "Q=A^3(P):\\ \\text{方向 }45^\\circ+135^\\circ=180^\\circ\\Rightarrow Q=(-\\sqrt2,\\ 0)"}, {"type": "text", "c": "再經 B⁴=旋轉120°：R 的方向角 =180°+120°=300°、長 √2，故 R=(√2/2, −√6/2)。"}, {"type": "math", "c": "\\vec{OR}\\cdot(1,0)=\\dfrac{\\sqrt2}{2},\\ |\\vec{OR}|=\\sqrt2\\Rightarrow \\cos\\theta=\\dfrac12\\Rightarrow \\theta=60^\\circ"}, {"type": "text", "c": "故 Q=(−√2, 0)，OR 與 (1,0) 的夾角為 60°。（與官方參考答案一致）"}], "stem": "img/114_stem.png"}, {"year": "114", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/114_q20.png", "answer": [{"t": "非選　"}, {"m": "\\angle OSP=60^\\circ"}, {"t": "、"}, {"m": "S=\\left(-\\tfrac{\\sqrt3}{3},1\\right)"}], "key": "OQ 沿 x 軸 → L 是水平線 y=1；求 L 與直線 OR 的交點 S，再算夾角。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp5"}, {"unit": "平面向量", "title": "考點5 向量的旋轉與坐標應用", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp5"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "由第 19 題，Q=(−√2, 0) 在 x 軸上，故直線 OQ 就是 x 軸。L 過 P(1,1) 且平行 OQ → L: y=1。"}, {"type": "text", "c": "直線 OR 方向 (√2/2, −√6/2) ∝ (1, −√3)，方程式 y=−√3 x。與 y=1 交於："}, {"type": "math", "c": "S=\\left(-\\dfrac{1}{\\sqrt3},\\ 1\\right)=\\left(-\\dfrac{\\sqrt3}{3},\\ 1\\right)"}, {"type": "text", "c": "在 S 算 ∠OSP：SP 沿 +x 方向，SO=(1/√3, −1)。"}, {"type": "math", "c": "\\cos\\angle OSP=\\dfrac{\\vec{SO}\\cdot(1,0)}{|\\vec{SO}|}=\\dfrac{1/\\sqrt3}{2/\\sqrt3}=\\dfrac12\\Rightarrow \\angle OSP=60^\\circ"}, {"type": "text", "c": "故 ∠OSP=60°、S=(−√3/3, 1)。（與官方參考答案一致）"}], "stem": "img/114_stem.png"}, {"year": "115", "num": 1, "type": "單選", "rate": "84%", "img": "img/115_q01.png", "answer": [{"t": "(2)　30 元"}], "key": "把「每種獎金 × 拿到它的機率」全部加起來，就是期望值。", "kaodian": [{"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp6"}, {"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp5"}], "steps": [{"type": "text", "c": "兩次抽籤互不影響，所以「兩次的結果」機率要相乘。"}, {"type": "text", "c": "• 兩次都抽到「吉」→ 得 180 元，機率是："}, {"type": "math", "c": "\\dfrac{1}{3}\\times\\dfrac{1}{3}=\\dfrac{1}{9}"}, {"type": "text", "c": "• 兩次都抽到「祥」→ 得 90 元，機率也是 1/9。其餘情況沒有獎金（算 0 元）。"}, {"type": "text", "c": "期望值 =（獎金 × 機率）逐項相加："}, {"type": "math", "c": "E=180\\times\\dfrac{1}{9}+90\\times\\dfrac{1}{9}=20+10=30\\ (\\text{元})"}, {"type": "text", "c": "所以答案是 (2) 30 元。"}]}, {"year": "115", "num": 2, "type": "單選", "rate": "55%", "img": "img/115_q02.png", "answer": [{"t": "(1)"}], "key": "[x] 是「不超過 x 的最大整數」；把每個根號夾在兩個整數之間，取整數部分。", "kaodian": [{"unit": "數與式", "title": "考點6 高斯函數（最大整數函數）", "url": "https://mathmap-kitty.github.io/web/115學測數學_數與式.html#kp6"}, {"unit": "數與式", "title": "考點3 數線上的點、距離、分點與根號估算", "url": "https://mathmap-kitty.github.io/web/115學測數學_數與式.html#kp3"}], "steps": [{"type": "text", "c": "記住整數平方：9²=81、10²=100、11²=121，用它們夾出根號在哪兩個整數之間。"}, {"type": "text", "c": "x=-20：√119 在 10 與 11 之間 → 取 10；√79 在 8 與 9 之間 → 取 8。"}, {"type": "math", "c": "f(-20)=[\\sqrt{119}]+[\\sqrt{79}]=10+8=18"}, {"type": "text", "c": "x=0：√99 在 9 與 10 之間 → 取 9，兩個都是 9。"}, {"type": "math", "c": "f(0)=[\\sqrt{99}]+[\\sqrt{99}]=9+9=18"}, {"type": "text", "c": "x=1：√98 取 9，√100 剛好等於 10。"}, {"type": "math", "c": "f(1)=[\\sqrt{98}]+[\\sqrt{100}]=9+10=19"}, {"type": "text", "c": "比較：f(-20)=f(0)=18，都小於 f(1)=19，即 f(-20) ≤ f(0) < f(1)，選 (1)。"}]}, {"year": "115", "num": 3, "type": "單選", "rate": "41%", "img": "img/115_q03.png", "answer": [{"t": "(1)　"}, {"m": "2^{-6/5}"}], "key": "指數每加一個公差 d，函數值就乘上 a^d——這個倍數正好是等比的公比。", "kaodian": [{"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp1"}, {"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp2"}], "steps": [{"type": "text", "c": "因為 f(x)=aˣ，相鄰兩項相除時指數相減，剛好差一個公差 10/3："}, {"type": "math", "c": "\\dfrac{f(c_2)}{f(c_1)}=a^{\\,c_2-c_1}=a^{10/3}=4\\ \\ (\\text{題目說公比是 }4)"}, {"type": "text", "c": "把 4 寫成 2 的次方（4=2²），解出底數 a："}, {"type": "math", "c": "a=4^{3/10}=\\left(2^{2}\\right)^{3/10}=2^{3/5}"}, {"type": "text", "c": "同樣地，f(10),f(8),f(6) 的公比是後項除前項，指數差 8-10=-2："}, {"type": "math", "c": "\\dfrac{f(8)}{f(10)}=a^{-2}=\\left(2^{3/5}\\right)^{-2}=2^{-6/5}"}, {"type": "text", "c": "所以公比是 2^(-6/5)，選 (1)。"}]}, {"year": "115", "num": 4, "type": "單選", "rate": "56%", "img": "img/115_q04.png", "answer": [{"t": "(3)　401"}], "key": "把「取 3 種材料」的情況分三類，分別數出「會產生幾種道具」再相加。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp2"}, {"unit": "排列組合與機率", "title": "考點1 計數原理與排列", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "注意問的是「共可合成幾種道具」，不是幾種取法。分三類："}, {"type": "text", "c": "① 3 種都是基本材料 → 不管哪三種，結果都是同一種草藥 → 只算 1 種。"}, {"type": "text", "c": "② 2 基本 + 1 進階 → 結果只看那 1 種進階材料（10 選 1），基本不影響 → 10 種食物。"}, {"type": "text", "c": "③ 其餘情況（1 基本+2 進階，或 3 進階）→ 每一種不同的材料組合都是不同藥水，所以「組合數」就是藥水種數："}, {"type": "math", "c": "\\binom{6}{1}\\binom{10}{2}+\\binom{10}{3}=6\\times 45+120=390"}, {"type": "text", "c": "三類相加：1 + 10 + 390 = 401，選 (3)。"}]}, {"year": "115", "num": 5, "type": "單選", "rate": "26%", "img": "img/115_q05.png", "answer": [{"t": "(5)　無窮多個"}], "key": "矩陣乘法可「拆開相加」；把已知的式子湊出目標，再加上「乘完變 0 的方向」得到一整條解。", "kaodian": [{"unit": "矩陣", "title": "考點1 矩陣的意義、相等與乘法", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp1"}, {"unit": "矩陣", "title": "考點4 一次聯立方程式與高斯消去法", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp4"}], "steps": [{"type": "text", "c": "矩陣作用在向量上可以拆開：A(u+v)=Au+Av。先把題目三個式子記成："}, {"type": "math", "c": "A(1,1,0)=(0,-1,1),\\quad A(0,-1,1)=(1,1,0),\\quad A(1,0,-1)=(0,0,0)"}, {"type": "text", "c": "想要 Av=(1,0,1)。觀察：把前兩式左右相加，右邊剛好是 (1,0,1)："}, {"type": "math", "c": "A\\big[(1,1,0)+(0,-1,1)\\big]=(0,-1,1)+(1,1,0)=(1,0,1)"}, {"type": "text", "c": "所以 v=(1,0,1) 是一個解。又因為 A(1,0,-1)=(0,0,0)，把 (1,0,-1) 的任意倍加上去，乘完多出來的是 0，值不變："}, {"type": "math", "c": "\\vec{v}=(1,0,1)+t\\,(1,0,-1)=(1+t,\\ 0,\\ 1-t)"}, {"type": "text", "c": "這些解的第二個分量都是 0，而「垂直於 (0,1,0)」正好就是第二分量為 0（內積=0）。所以每個解都符合，共有無窮多個，選 (5)。"}]}, {"year": "115", "num": 6, "type": "單選", "rate": "37%", "img": "img/115_q06.png", "answer": [{"t": "(2)　2 個"}], "key": "等腰有三種可能（哪一邊是頂角）；算完別忘了把「三點共線」的假三角形刪掉。", "kaodian": [{"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp2"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "先算 AB=5。設 C=(c, -6)（在直線 y=-6 上），分三種情形："}, {"type": "text", "c": "① CA=CB（C 到 A、B 一樣遠）→ C 在 AB 的中垂線上，中垂線和 y=-6 交在 1 個點（c=-15/2）。"}, {"type": "math", "c": "②\\ \\overline{AC}=\\overline{AB}=5:\\ (c-2)^2+(-6+2)^2=25\\Rightarrow c=5\\ \\text{或}\\ -1"}, {"type": "math", "c": "③\\ \\overline{BC}=\\overline{AB}=5:\\ (c+1)^2+(-6-2)^2=25\\ \\text{（算出無解）}"}, {"type": "text", "c": "初步得到 c=-15/2、5、-1 三個點。但 C=(5,-6) 剛好落在直線 AB 上（A、B、C 連成一直線），不是三角形，要刪掉！"}, {"type": "text", "c": "所以真正合格的只有 (-15/2,-6) 和 (-1,-6)，共 2 個，選 (2)。（見右圖）"}], "fig": "img/115_fig_q06.png"}, {"year": "115", "num": 7, "type": "多選", "rate": "74%（全對率 66%）", "img": "img/115_q07.png", "answer": [{"t": "(3)(4)"}], "key": "把兩個不等式各畫成半平面，交集在哪個象限，用一個代表點去試最快。", "kaodian": [{"unit": "直線與圓", "title": "考點5 平面區域與線性規劃", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp5"}], "steps": [{"type": "text", "c": "兩條件整理成：y < 2x-3（在這條線下方）且 y < -x/2 - 1/2（在那條線下方）。"}, {"type": "text", "c": "第一、二象限：要 y 是正的，但第二式要 y < 負數，矛盾 → 不可能。"}, {"type": "text", "c": "第三象限：試 (-10,-24)，兩式都成立 → 可以。"}, {"type": "text", "c": "第四象限：試 (3,-3)，兩式都成立 → 可以。"}, {"type": "text", "c": "x 軸（y=0）：第一式要 x>3/2，第二式要 x<-1，不能同時 → 不可能。"}, {"type": "text", "c": "所以點可能在第三、第四象限，選 (3)(4)。"}]}, {"year": "115", "num": 8, "type": "多選", "rate": "70%（全對率 56%）", "img": "img/115_q08.png", "answer": [{"t": "(2)(5)"}], "key": "先算 A²，發現 A²=2A+I（可直接驗證）；再利用「A 對稱 → Aⁿ 也對稱」。", "kaodian": [{"unit": "矩陣", "title": "考點2 矩陣的高次方 Aⁿ", "url": "https://mathmap-kitty.github.io/web/115學測數學_矩陣.html#kp2"}, {"unit": "數列與級數", "title": "考點3 遞迴數列：構造等比與數學歸納法", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp3"}], "steps": [{"type": "math", "c": "A=\\begin{bmatrix}2&1\\\\1&0\\end{bmatrix}\\Rightarrow A^2=\\begin{bmatrix}5&2\\\\2&1\\end{bmatrix}"}, {"type": "text", "c": "(1) 由 A² 讀出 b₂=2、c₂=2，兩者相等，不是 b₂<c₂ → 錯。"}, {"type": "text", "c": "(2) 直接檢查：2A+I 的四個位置算出來剛好等於 A²（下式），對！"}, {"type": "math", "c": "2A+\\begin{bmatrix}1&0\\\\0&1\\end{bmatrix}=\\begin{bmatrix}5&2\\\\2&1\\end{bmatrix}=A^2"}, {"type": "text", "c": "(3) 兩邊同乘 Aⁿ 得 A^(n+2)=2A^(n+1)+Aⁿ，所以每格都是 x_(n+2)=2x_(n+1)+x_n，和題目寫的不同 → 錯。"}, {"type": "text", "c": "(4) 矩陣乘直行 (0,1) 等於「取出第二直行」＝(bₙ,dₙ)，不會變成下一項 → 錯。"}, {"type": "text", "c": "(5) A 對稱，所以 Aⁿ 也對稱（bₙ=cₙ）。把 Aⁿ 平方看 A^(2n) 的左上與右下："}, {"type": "math", "c": "a_{2n}=a_n^{2}+b_n^{2},\\quad d_{2n}=b_n^{2}+d_n^{2}\\ \\Rightarrow\\ d_{2n}-a_{2n}=d_n^{2}-a_n^{2}"}, {"type": "text", "c": "相減時 bₙ² 消掉 → 對。故選 (2)(5)。"}]}, {"year": "115", "num": 9, "type": "多選", "rate": "44%（全對率 21%）", "img": "img/115_q09.png", "answer": [{"t": "(1)(2)(4)"}], "key": "T 分數是把原始分做一條直線變換：斜率 10/σ。σ 越小，同樣的分差被放得越大。", "kaodian": [{"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp1"}, {"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "https://mathmap-kitty.github.io/web/115學測數學_數據分析.html#kp3"}], "steps": [{"type": "math", "c": "T=50+\\dfrac{10}{\\sigma}(S-\\mu):\\quad \\text{數學斜率}=\\dfrac{10}{12}=\\dfrac{5}{6},\\ \\ \\text{英文斜率}=\\dfrac{10}{8}=\\dfrac{5}{4}"}, {"type": "text", "c": "(1) 英文 S=52：T=50+(5/4)×(52-60)=50-10=40 → 對。"}, {"type": "text", "c": "(2) 數學：T-S = -S/6，因成績 S≥0 所以 T-S≤0，即 T 不超過原始分 → 對。"}, {"type": "text", "c": "(3) 英文的放大倍率(5/4)比數學(5/6)大。就算兩科原始平均較高，換成 T 分數後不一定較高（可舉反例）→ 錯。"}, {"type": "text", "c": "(4) 要 T≥40：數學需 S≥48、英文需 S≥52。數學的及格門檻比較低 → 對。"}, {"type": "text", "c": "(5) T 分數會把兩科標準差都變成 10，所以「數學對英文」迴歸斜率＝相關係數 r；但用原始分是 r×(12/8)，兩者不同 → 錯。"}, {"type": "text", "c": "故選 (1)(2)(4)。"}]}, {"year": "115", "num": 10, "type": "多選", "rate": "36%（全對率 10%）", "img": "img/115_q10.png", "answer": [{"t": "(1)(5)"}], "key": "梯形對角線的交點會依「上底:下底」分割；面積用行列式算，再逐項檢查。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp2"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp3"}, {"unit": "平面向量", "title": "考點4 行列式與平行四邊形面積", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp4"}], "steps": [{"type": "text", "c": "設 A 為原點，AB=(2,-6)、AD=(1,5)。三角形 ABD 面積用行列式：½|2·5-(-6)·1|=8。"}, {"type": "text", "c": "梯形中 AB∥DC，對角線交點 E 使 BE:ED = AB:DC = 1:k。由「E 到 AB 的高 = D 的高的 1/(1+k)」："}, {"type": "math", "c": "\\dfrac{1}{1+k}\\times 8=3\\ \\Rightarrow\\ k=\\dfrac{5}{3},\\quad \\text{可求得 }C=\\left(\\tfrac{13}{3},-5\\right)"}, {"type": "math", "c": "(1)\\ \\cos\\angle BAD=\\dfrac{\\vec{AB}\\cdot\\vec{AD}}{|\\vec{AB}||\\vec{AD}|}=\\dfrac{2-30}{2\\sqrt{10}\\cdot\\sqrt{26}}=\\dfrac{-7\\sqrt{65}}{65}\\ \\text{（對）}"}, {"type": "text", "c": "(2) △ABD=8，不是 9 → 錯。　(3) 由分點求 AE=(3/8)AC=(13/8, -15/8)，不是 (3/2,1/2) → 錯。"}, {"type": "math", "c": "(4)\\ \\text{四邊形面積}=\\dfrac{64}{3}\\neq\\dfrac{65}{3}\\ \\text{（錯）};\\quad (5)\\ |\\vec{BC}|=\\dfrac{\\sqrt{58}}{3}<\\dfrac{8}{3}\\ \\text{（對）}"}, {"type": "text", "c": "故選 (1)(5)。"}]}, {"year": "115", "num": 11, "type": "多選", "rate": "33%（全對率 12%）", "img": "img/115_q11.png", "answer": [{"t": "(2)(4)"}], "key": "cos 圖形週期是 4、左右對稱；而且不管 m 是多少，直線都通過 (0,1)——它一定是交點。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp4"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "Γ:y=cos((π/2)x) 週期為 4。直線 y=mx+1 通過 (0,1)，而 Γ 在 x=0 也等於 1，所以 (0,1) 永遠是交點。"}, {"type": "text", "c": "(1) (0,1) 是交點，但它的 x=0 不是負的 → 錯。"}, {"type": "text", "c": "(2) cos 是偶函數，圖形左右對稱；若 (a,b) 是交點，鏡射到 (-a,b) 就是 L₋ₘ 的交點 → 對。"}, {"type": "math", "c": "(3)\\ x=\\tfrac{20}{3}\\ \\text{代入}:\\ \\cos\\tfrac{10\\pi}{3}=-\\tfrac{1}{2}\\neq\\tfrac{1}{2}\\ \\text{（此點不在 }\\Gamma\\text{ 上，錯）}"}, {"type": "math", "c": "(4)\\ \\cos\\tfrac{\\pi x}{2}=-1\\Rightarrow x=4k+2;\\ \\text{又}\\ x=-\\tfrac{2}{m}\\Rightarrow \\tfrac{1}{m}=-(2k+1)\\ \\text{是奇數（對）}"}, {"type": "text", "c": "(5) 舉 m=1：它和 x 軸交點 (-1,0) 確實是交點，但整條線和 Γ 交在 x=-2,-1,0 共 3 個（奇數）→ 錯。"}, {"type": "text", "c": "故選 (2)(4)。（見右圖）"}]}, {"year": "115", "num": 12, "type": "多選", "rate": "28%（全對率 11%）", "img": "img/115_q12.png", "answer": [{"t": "(2)(4)"}], "key": "三次函數的對稱中心（反曲點）x 座標＝-（x²係數）/(3×x³係數)；f-g=0 決定交點個數。", "kaodian": [{"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp5"}, {"unit": "多項式函數", "title": "考點3 多項式方程式與不等式的解法", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp3"}], "steps": [{"type": "text", "c": "設 f(x)=x³+px²+qx+r，則 g=f-(2x³+2x)=-x³+px²+(q-2)x+r。"}, {"type": "text", "c": "對稱中心的 x 座標：f 是 -p/3，g 是 +p/3（g 的 x³係數是 -1），兩者相加："}, {"type": "math", "c": "a_1+a_2=-\\dfrac{p}{3}+\\dfrac{p}{3}=0\\ \\text{（一定是 0，(2) 對）}"}, {"type": "text", "c": "(1) 交點看 f-g=0：2x³+2x=2x(x²+1)=0 只有 x=0 一個實根 → 只交 1 點 → 錯。"}, {"type": "math", "c": "(3)\\ b_1+b_2=\\dfrac{4p^{3}}{27}-\\dfrac{2p}{3}+2r\\ \\text{（會隨 }p,r\\text{ 改變，不唯一）}\\Rightarrow \\text{錯}"}, {"type": "text", "c": "(4) a₁=a₂ 表示 p=0，此時 b₁=f(0)=r=g(0)=b₂ → 對。"}, {"type": "text", "c": "(5) b₁=b₂ 可化成 p(1-q)=0；只要取 q=1、p≠0，就有 b₁=b₂ 但 a₁≠a₂ → 錯。"}, {"type": "text", "c": "故選 (2)(4)。"}]}, {"year": "115", "num": 13, "type": "選填", "rate": "73%", "img": "img/115_q13.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{9}{10}"}], "key": "條件機率＝（碩士又通過的機率）÷（全部通過的機率）。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_排列組合與機率.html#kp4"}], "steps": [{"type": "text", "c": "學士佔 1/4、其中 1/5 通過；碩士佔 3/4、其中 3/5 通過。先算「隨便抽一位會通過」的總機率："}, {"type": "math", "c": "P(\\text{通過})=\\dfrac{1}{4}\\cdot\\dfrac{1}{5}+\\dfrac{3}{4}\\cdot\\dfrac{3}{5}=\\dfrac{1}{20}+\\dfrac{9}{20}=\\dfrac{1}{2}"}, {"type": "text", "c": "題目問「已知這人通過，他是碩士」的機率，用通過中屬於碩士的那部分去除以總通過："}, {"type": "math", "c": "P(\\text{碩}\\mid\\text{通過})=\\dfrac{\\ \\frac{3}{4}\\cdot\\frac{3}{5}\\ }{\\frac{1}{2}}=\\dfrac{9/20}{1/2}=\\dfrac{9}{10}"}, {"type": "text", "c": "答案 9/10。"}]}, {"year": "115", "num": 14, "type": "選填", "rate": "19%", "img": "img/115_q14.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{1}{4}"}], "key": "向量垂直 → 內積等於 0，先把 a 用 b 表示；再對 a+b 配方求最大。", "kaodian": [{"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "https://mathmap-kitty.github.io/web/115學測數學_平面向量.html#kp3"}, {"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp2"}], "steps": [{"type": "text", "c": "直線 y=bx-1 的方向向量是 (1,b)。向量 (a,b) 垂直於它，內積為 0："}, {"type": "math", "c": "(a,b)\\cdot(1,b)=a+b^{2}=0\\ \\Rightarrow\\ a=-b^{2}"}, {"type": "text", "c": "代回 a+b，變成只含 b 的二次式，配方找最大："}, {"type": "math", "c": "a+b=-b^{2}+b=-\\left(b-\\dfrac{1}{2}\\right)^{2}+\\dfrac{1}{4}\\le \\dfrac{1}{4}"}, {"type": "text", "c": "當 b=1/2 時達到最大，a+b 的最大值是 1/4。"}]}, {"year": "115", "num": 15, "type": "選填", "rate": "31%", "img": "img/115_q15.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{b}{a}=\\dfrac{3}{2}"}], "key": "a,b,c 等差 → 三點的 x 座標等距；此時「共線」就等於 y 座標也成等差。", "kaodian": [{"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "https://mathmap-kitty.github.io/web/115學測數學_指數與對數.html#kp2"}, {"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "https://mathmap-kitty.github.io/web/115學測數學_數列與級數.html#kp1"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率（三點共線）", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "因為 a,b,c 等差，x 座標間距 b-a 和 c-b 相等。x 等距時，三點共線 ⟺ y 也成等差："}, {"type": "math", "c": "2\\log(4b)=\\log(3a)+\\log(6c)"}, {"type": "text", "c": "用對數運算（係數變次方、相加變相乘）："}, {"type": "math", "c": "\\log(4b)^{2}=\\log(3a\\cdot 6c)\\Rightarrow 16b^{2}=18ac\\Rightarrow 8b^{2}=9ac"}, {"type": "text", "c": "再代 c=2b-a（等差：a+c=2b），並全部除以 a²："}, {"type": "math", "c": "8\\left(\\tfrac{b}{a}\\right)^{2}-18\\left(\\tfrac{b}{a}\\right)+9=0\\Rightarrow \\tfrac{b}{a}=\\tfrac{3}{2}\\ \\text{或}\\ \\tfrac{3}{4}"}, {"type": "text", "c": "因為 a<b（b/a>1），取 b/a = 3/2。"}]}, {"year": "115", "num": 16, "type": "選填", "rate": "20%", "img": "img/115_q16.png", "answer": [{"t": "選填　"}, {"m": "\\overline{PQ}=\\dfrac{3\\sqrt{5}}{2}"}], "key": "用兩根寫出拋物線、頂點在直線上定出係數；平移後頂點還在線上且過 B，解出移動量。", "kaodian": [{"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "https://mathmap-kitty.github.io/web/115學測數學_多項式函數.html#kp2"}, {"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "https://mathmap-kitty.github.io/web/115學測數學_直線與圓.html#kp2"}], "steps": [{"type": "text", "c": "由與 x 軸交點 ±1/2 寫成 f(x)=k(x²-1/4)。頂點在 x=0，代入直線 y=1+2x 得頂點 y=1："}, {"type": "math", "c": "-\\dfrac{k}{4}=1\\Rightarrow k=-4,\\quad f(x)=-4x^{2}+1,\\ \\ P=(0,1)"}, {"type": "text", "c": "平移後頂點 Q=(h, 1+2h)（還在直線上），圖形 y=-4(x-h)²+(1+2h) 通過 B(1/2, 0)："}, {"type": "math", "c": "4h^{2}-6h=0\\Rightarrow h=0\\,(\\text{就是}P)\\ \\text{或}\\ h=\\tfrac{3}{2}\\Rightarrow Q=\\left(\\tfrac{3}{2},4\\right)"}, {"type": "text", "c": "P、Q 相異取 h=3/2，再用兩點距離："}, {"type": "math", "c": "\\overline{PQ}=\\sqrt{\\left(\\tfrac{3}{2}\\right)^{2}+(4-1)^{2}}=\\sqrt{\\tfrac{45}{4}}=\\dfrac{3\\sqrt{5}}{2}"}]}, {"year": "115", "num": 17, "type": "選填", "rate": "6%", "img": "img/115_q17.png", "answer": [{"t": "選填　"}, {"m": "k=\\dfrac{3}{11}"}], "key": "先把角關係理清楚，在三角形 BCD 用正弦定理配合 BC=2BD 解出角，再用三倍角算比值。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp2"}, {"unit": "三角", "title": "考點5 和差角與倍角", "url": "https://mathmap-kitty.github.io/web/115學測數學_三角.html#kp5"}], "steps": [{"type": "text", "c": "設 ∠ACD=φ，則 ∠BCD=2φ，整個 ∠ACB=3φ。因 ∠A=90°，所以 ∠ABC=90°-3φ。"}, {"type": "text", "c": "在三角形 BCD 中，∠BDC=180°-2φ-(90°-3φ)=90°+φ。對它用正弦定理，並代入 BC=2BD："}, {"type": "math", "c": "\\dfrac{BC}{BD}=\\dfrac{\\sin(90^\\circ+\\varphi)}{\\sin 2\\varphi}=\\dfrac{\\cos\\varphi}{2\\sin\\varphi\\cos\\varphi}=\\dfrac{1}{2\\sin\\varphi}=2\\Rightarrow \\sin\\varphi=\\dfrac{1}{4}"}, {"type": "text", "c": "在直角三角形 ABC 裡令 AC=1，則 AD=tanφ、AB=tan3φ；用三倍角公式算出 tan3φ："}, {"type": "math", "c": "k=\\dfrac{\\overline{AD}}{\\overline{AB}}=\\dfrac{\\tan\\varphi}{\\tan 3\\varphi}=\\dfrac{1/\\sqrt{15}}{\\,11/(3\\sqrt{15})\\,}=\\dfrac{3}{11}"}]}, {"year": "115", "num": 18, "type": "混合題（單選 3 分）", "rate": "69%", "img": "img/115_q18.png", "answer": [{"t": "(3)　"}, {"m": "5\\sqrt{3}"}], "key": "平行四邊形面積＝兩鄰邊外積向量的長度。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp3"}], "steps": [{"type": "text", "c": "ABCD 以 AB、AD 為兩鄰邊。平行四邊形面積就等於外積 AB×AD 的長度："}, {"type": "math", "c": "[ABCD]=\\left|\\vec{AB}\\times\\vec{AD}\\right|=\\left|(-5,5,5)\\right|=\\sqrt{25+25+25}=\\sqrt{75}=5\\sqrt{3}"}, {"type": "text", "c": "選 (3)。"}], "stem": "img/115_stem.png"}, {"year": "115", "num": 19, "type": "非選擇題（4 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/115_q19.png", "answer": [{"t": "非選　"}, {"m": "-x+y+z=1"}], "key": "平面 ABCD 的法向量就用 AB×AD；再代入平面上的已知點 B。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp4"}], "steps": [{"type": "text", "c": "ABCD 在同一平面上，它的法向量可取 AB×AD=(-5,5,5)，化簡成 (-1,1,1)。"}, {"type": "text", "c": "平面通過 B(1,2,0)，用「法向量·(位置差)=0」寫式："}, {"type": "math", "c": "-1(x-1)+1(y-2)+1(z-0)=0\\ \\Rightarrow\\ -x+y+z=1"}, {"type": "text", "c": "所以平面 ABCD 的方程式是 -x+y+z=1（也可寫成 x-y-z+1=0）。"}], "stem": "img/115_stem.png"}, {"year": "115", "num": 20, "type": "非選擇題（8 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/115_q20.png", "answer": [{"t": "非選　體積 "}, {"m": "V=10"}, {"t": "，最長距離 "}, {"m": "\\sqrt{94}"}], "key": "外積必垂直於它的兩個因子 → 反推出 AP 方向；體積=|AP·(AB×AD)|；最遠點一定是某個頂點。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp3"}, {"unit": "空間向量", "title": "考點1 空間坐標、距離與正立方體", "url": "https://mathmap-kitty.github.io/web/115學測數學_空間向量.html#kp1"}], "steps": [{"type": "text", "c": "外積一定垂直於相乘的兩個向量，所以 AP 同時垂直於 AD×AP 和 AP×AB。因此 AP 平行於這兩者的外積："}, {"type": "math", "c": "(-2,0,-4)\\times(6,-10,-8)=(-40,-40,20)\\ \\parallel\\ (-2,-2,1)"}, {"type": "text", "c": "(-2,-2,1) 長度為 3，而 |AP|=6，所以 AP=2×(-2,-2,1)=(-4,-4,2)。體積用「AP 與底面外積的內積」："}, {"type": "math", "c": "V=\\left|\\vec{AP}\\cdot(\\vec{AB}\\times\\vec{AD})\\right|=\\left|(-4,-4,2)\\cdot(-5,5,5)\\right|=|20-20+10|=10"}, {"type": "text", "c": "同法解得 AB=(-1,1,-2)、AD=(-2,-3,1)。封閉立體上離 A 最遠的點一定是頂點；各頂點相對 A 是 AB、AD、AP 的 0/1 組合，逐一算長度比較："}, {"type": "math", "c": "\\overline{AB}=\\sqrt{6},\\ \\overline{AD}=\\sqrt{14},\\ |\\vec{AB}+\\vec{AP}|=\\sqrt{34},\\ |\\vec{AB}+\\vec{AD}+\\vec{AP}|=\\sqrt{86},\\ |\\vec{AD}+\\vec{AP}|=\\sqrt{94}"}, {"type": "text", "c": "最大的是 √94（發生在頂點 AD+AP，即圖中的 S 點）。所以體積為 10、六面體上距 A 的最長距離為 √94。"}], "stem": "img/115_stem.png"}];